pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gap 1..9 heavily penalized
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (good packing).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 20.0;

    // If this is the last fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just below the next item size (dead space for lookahead).
    if next_item_size > 0 && post_residual >= 1 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is large.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 2.0;
        score -= mean_residual * 0.3;
    } else {
        // New-bin candidate: slightly discouraged unless residuals everywhere are poor.
        score += 25.0 + mean_residual * 0.5;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with progress-scaled weights
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
            // near-exact chain: extra reward
            if slack <= 2.0 {
                score -= 25.0 * (1.0 - progress * 0.5);
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else {
        score = post_residual as f64 * 3.0;
        if bin_residual == bin_capacity {
            score += 200.0; // never open a bin for the last item
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // Best-fit flavor with tightness coupling
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Awkward dead zone, scaled by progress (early stream more tolerant)
    if post_residual > 0 && post_residual < 12 {
        score += 120.0 + 40.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 30.0;
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 70.0;
    }

    // NEW-BIN CANDIDATE handling: default penalty, conditional relief
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            // big next item that won't fit leftovers anywhere: new bin is fine
            if next_item_size > bin_capacity / 2 {
                score -= 20.0;
            }
            // item + next fills a fresh bin exactly
            if item_size + next_item_size == bin_capacity {
                score -= 14.0;
            }
            // large item dominating a bin: fresh bin acceptable
            if item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            // many alternatives exist: strongly discourage new bin
            if fitting_bins_count > 2 {
                score += 18.0;
            }
            if mean_residual > 25.0 {
                score += 8.0;
            }
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into tight ones
    if open_bins_count > 3 && fitting_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln();
        if post_residual >= next_item_size.max(1) {
            score -= 4.0 * pressure;
        } else {
            score += 3.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: punish small unusable gaps, stronger early in stream.
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 6 {
        score -= 20.0;
    }

    // Tightness coupling: reward filling a bin densely with this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure via log, modulated by slack in the system.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Lookahead: next item fits the resulting gap -> valuable placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last resort: only fitting bin -> strong preference over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // Large next item: safer to strand it in a fresh bin now.
            if next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 4.0;
            }
            // Large current item also favors a fresh bin.
            if item_size > 50 {
                score -= 10.0;
            }
        }
        // Late in stream: consolidate, avoid opening bins.
        if mean_residual > 25.0 {
            score += 6.0 + progress * 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish gaps that are too small to hold
    // the smallest possible item (min size 1..10 zone) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // worst for tiny unusable slivers
    }

    // Reward near-perfect fits (post_residual within 10 of a fully packed bin).
    if post_residual <= 10 {
        score -= 25.0;
    }

    // Exact fit: strongly favored.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the resulting gap, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap won't hold next item -> likely dead space
        score += 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer tighter sets.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than average (fill the emptiest-tight bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it moderately attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score = 55.0 + (open_bins_count as f64) * 0.8;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If item is large, a fresh bin is safer (avoids stranding big items).
        if item_size > 50 {
            score -= 35.0;
        }
        // If no other bin fits (fitting_bins_count==1 refers to this new bin too),
        // opening is unavoidable; make it neutral-low.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    score
}

