pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (below the minimum item size) are wasted space.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Dead-space band: gaps that are hard to fill (small but not zero).
    if post_residual > 0 && post_residual <= 20 {
        score += 25.0 - 0.5 * post_residual as f64;
    }

    // Reward tight fits strongly.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

