    // existing bins over opening new ones; when few bins are open, be lenient.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (2.0 + 8.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 30.0 + 20.0 * pressure;
    } else {
        score -= 8.0 * pressure.min(3.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap; penalize proportionally to gap size.
        score += 0.3 * post_residual as f64;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller residuals (consolidate space).
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

