}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that fall into "dead zones": too small for smallest useful items.
    if post_residual < 10 {
        score += 1000.0; // unusable sliver
    } else if frac < 0.25 {
        score += 40.0;   // likely dead space
    } else if frac < 0.5 {
        score += 10.0;
    } else if frac < 0.75 {
        score -= 5.0;
    } else {
        score -= 15.0;   // roomy residual, keep usable
    }

    // Harmonic match: does next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // reward smooth division: post_residual % next_item_size small
            if post_residual % next_item_size.max(1) == 0 {
                score -= 60.0;
            }
            score -= (20.0 - slack.min(20) as f64) * 2.0;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot class
            score += ((next_item_size - post_residual) % 25) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Early stream: be more tolerant of spreading items (better future packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0;

    // New-bin candidate: make it attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        let mean_bad = (mean_residual - frac * bin_capacity as f64).abs();
        if mean_residual < 15.0 || post_residual as f64 > mean_residual + 30.0 {
            score -= 50.0;
        } else {
            score += 30.0 + mean_bad * 0.1;
        }
    }

    // Integer-division threshold coupling on post_residual classes (harmonic bins of 25).
    let class = post_residual / 25;
    score -= class as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = x * x * (3.0 - 2.0 * x) * cap * 0.5 + pr;

    // Smooth interaction: as stream progresses, increasingly penalize large dead space.
    score += 8.0 * progress * x * x * cap;

    // Reward filling bins tightly when many bins are open (consolidation pressure).
    score -= 4.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x) * (1.0 - x);

    // Deviation from mean residual: prefer bins whose residual after placement is near mean
    // (keeps a portfolio of usable gaps), penalize extremes smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead coupling: if next item would fit in the post residual, reward leaving that gap.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let gap_quality = 1.0 - ((pr - nx) / cap).abs();
        score -= 6.0 * fits_next * gap_quality.max(0.0);
        // Penalize post residuals that are too small for the next item (wasted sliver).
        let waste = ((nx - pr) / cap).max(0.0);
        score += 5.0 * (1.0 - fits_next) * waste * waste * cap;
    }

    // New-bin candidate: neutral-ish score that decreases with remaining stream so late
    // items prefer fresh bins over fragmenting old ones.
    if bin_residual == bin_capacity {
        score = cap * (1.0 - progress) * 0.6 + 2.0;
    }

    score
}

