pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: penalize "dead" residue classes ---
    // Residuals that are too small to ever accept a plausible future item (1..=9)
    // are pure dead space; residuals in sweet spots (multiples of 10 / 25) stay usable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure: best possible outcome
    } else if pr < 10 {
        score += 60.0; // unusable sliver
    } else {
        // reward alignment with harmonic divisions of capacity
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 18.0; }
        if pr % 50 == 0 { score -= 22.0; }
        // mid-range residuals (40..70) are the most reusable: reward them
        if pr >= 40 && pr <= 70 { score -= 10.0; }
        // large leftover wastes a big chunk of the bin: mild penalty
        if pr > 80 { score += 8.0; }
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item nests here: strong reward, scaled by how snugly it fits
            let snug = 1.0 - (pr as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 25.0 + 20.0 * snug;
            // harmonic bonus if next item closes this bin exactly
            if next_item_size == pr { score -= 30.0; }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 5.0 + 0.15 * (next_item_size as f64 - pr as f64);
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // (mean residual low) or the item is huge and would leave dead space.
        let tight = (mean_residual < 25.0) as i32 as f64;
        let huge = (item_size > 70) as i32 as f64;
        score += 30.0 - 20.0 * tight - 10.0 * huge;
        // late in the stream, prefer compacting into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // --- Mild pressure toward bins tighter than the mean (best-fit flavor) ---
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // --- Tie-break by fill level: fuller bins get slight preference ---
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..100, conservatively assume items >= 10)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only usable by tiny items; moderate penalty
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    } else {
        // Large leftover space is flexible; reward it mildly
        score -= 0.15 * post_residual as f64;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly
    // into the post_residual, this placement sets up a perfect chain.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 40.0;
    }
    // If next item cannot fit here and post_residual is small, dead space is locked
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.35 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // there are already several open bins, unless the fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if mean residual is tiny (all bins nearly full), opening is fine
        score -= 0.6 * mean_residual;
    }

    // Alignment with mean residual: prefer bins whose post_residual stays
    // near the mean (keeps the bin population homogeneous and reusable).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near match between post_residual and next item size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-gap / 12.0).exp();
        // Perfect chain: item fits exactly, next item fills the remainder exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a residual that neither fits next item nor is reusable.
        if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 25.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize creating small unusable slivers of dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below
    // the minimum item size is catastrophic waste.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (1.0 - gap as f64 / bin_capacity as f64) * 12.0;
    }
    // If next item cannot fit here, mild penalty for leaving awkward space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the emptiest (best fit) slightly.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Prefer fuller bins (small bin_residual) to consolidate load.
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Global pressure: when mean residual across open bins is low,
    // preserve remaining space less aggressively; when high, encourage
    // filling existing bins rather than opening new ones.
    score -= mean_residual * 0.05;

    // New-bin candidate logic: opening a fresh bin is only attractive
    // early in the stream or when the current item would leave a very
    // awkward remainder in any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = post_residual > 0 && post_residual < 10;
        if awkward || (progress < 0.25 && open_bins_count > 3) {
            score -= 10.0;
        } else {
            // Penalize new bins: cost of a fresh bin is the full capacity.
            score += 30.0;
        }
    }

    // Time horizon: late in the stream, waste matters more (no future
    // items to fill leftover space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty for tiny dead space
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // early on, larger residuals are more acceptable; later, tighten packing
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress);
    score *= progress_coupling;

    // Non-linear interaction: penalize residual that is small but not zero
    // (dead space), scaled by how far along the stream we are
    let dead = norm_pr * (1.0 - norm_pr);
    score += 30.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can still host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mild preference to fill existing bins when many are open
    score += 0.05 * (open_bins_count as f64) * (1.0 - norm_pr);

    // Keep new-bin candidate from winning unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class boundaries at multiples of 10 (typical item granularity) and small dead zones.
    let pr = post_residual as f64;
    let class = (post_residual / 10) as f64;
    let rem = (post_residual % 10) as f64;

    // Reward residuals that are exactly reusable by common item sizes (10..80).
    // Perfect fit (post_residual == 0) is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        // tiny leftover: nearly dead space, penalize
        score += 8.0 - rem * 0.8;
    } else {
        // Reward keeping residual in coarse harmonic classes (multiples of 10)
        score -= class * 0.6;
        // Penalize off-class remainder (dead space within the class)
        score += rem * 0.35;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits here: strong reward, scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
            // next item won't fit: penalize, worse if the miss is small (near-miss)
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(30.0) * 0.25;
        }
        // Harmonic compatibility: next_item_size class vs post_residual class
        let ni_class = (next_item_size / 10) as f64;
        if (ni_class - class).abs() < 0.5 {
            score -= 4.0; // same harmonic decade: likely future compatibility
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer bins where the fit is tightest (already via post_residual)
        score += (fitting_bins_count as f64 - 1.0) * 0.4;
    }

    // New-bin candidate: only attractive when open bins would leave very bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when stream is early
        // (more future to amortize) and when many bins are already open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_cost = 55.0 + 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.7 {
            new_cost -= 10.0; // big next item: fresh bin is useful
        }
        score = new_cost;
    }

    // Mild preference to consolidate into bins below mean residual (fill emptier bins first
    // keeps tight bins available for small future items).
    score += (mean_residual - pr).max(-20.0).min(20.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish gaps that are too small to hold
    // the smallest possible item (min size 1..10 zone) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // worst for tiny unusable slivers
    }

    // Reward near-perfect fits (post_residual within 10 of a fully packed bin).
    if post_residual <= 10 {
        score -= 25.0;
    }

    // Exact fit: strongly favored.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the resulting gap, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap won't hold next item -> likely dead space
        score += 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer tighter sets.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than average (fill the emptiest-tight bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it moderately attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score = 55.0 + (open_bins_count as f64) * 0.8;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If item is large, a fresh bin is safer (avoids stranding big items).
        if item_size > 50 {
            score -= 35.0;
        }
        // If no other bin fits (fitting_bins_count==1 refers to this new bin too),
        // opening is unavoidable; make it neutral-low.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chaining of two items).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-item pairing
        } else if post_residual as f64 > next {
            // next item still fits afterwards: mildly good
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit in leftover: dead space risk
            score += 10.0 + 0.5 * diff;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average leftover is efficient packing.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New empty bin candidate: neutral-ish baseline so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 5.0 + 0.3 * (open_bins_count as f64);
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 20.0; // fresh bin can host a clean 2-item pair
        }
    }

    // Late in the stream, tighten packing (avoid opening bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fits are gold.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize dead space relative to capacity, non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 120.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            // Bonus if next item would then fit snugly.
            let pr2 = post_residual as i64 - next_item_size as i64;
            if pr2 <= 10 {
                score -= 40.0;
            }
        } else {
            // Post-residual becomes dead space for the next item.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer filling bins that already have low residual (tighter packing).
    score += (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.5;

    // Time horizon: early in stream, allow more bins (better future flexibility);
    // late in stream, be conservative and reuse bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (0.5 - progress) * 40.0;

    // Many open bins: encourage reuse over opening yet another bin.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it attractive only when item is large relative to
    // typical residual or no open bin fits well; otherwise discourage.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        score -= 80.0 * tightness;      // large items start fresh bins cheaply
        score += 90.0 * (1.0 - tightness); // small items should reuse
        if fitting_bins_count == 0 {
            score -= 300.0;             // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, waste is cheaper (bins will be reused later); late, waste is costly.
    let mut score = norm_pr * norm_pr * (0.6 + 1.8 * progress) * cap;

    // Smooth cubic coupling: post_residual vs next item fit.
    // If next item fits the post residual, reward (subtract); if not, penalize.
    let next_fit_gap = (norm_next - norm_pr).abs();
    score += next_fit_gap * next_fit_gap * cap * (0.5 + 0.5 * progress);

    // Smooth reward for tight fits: post_residual near zero is best.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * cap * 0.8;

    // Interaction: filling a bin deeply is better when many bins are open (consolidation pressure).
    let fill = norm_item;
    score -= fill * fill * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), scaled smoothly by how well it fits.
    if fitting_bins_count == 1 {
        score -= cap * (1.2 + 0.6 * progress);
    }

    // Mild attraction to bins whose residual is near the mean (keep residuals homogeneous),
    // expressed as a smooth quadratic dispersion penalty.
    let disp = (pr - mean_residual) / cap;
    score += disp * disp * cap * 1.5;

    // New-bin candidate: empty bin has post_residual == capacity; penalize opening
    // new bins unless the item is large relative to capacity (smooth in item size).
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 1.2 * (1.0 - norm_item)) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic class of the dead space left behind (integer division thresholds).
    if pr == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else {
        let class = pr / 10; // harmonic band of residual capacity
        score += match class {
            0 => 15.0,  // 1..=9 left: near-perfect, slightly wasteful
            1 => 6.0,   // 10..=19: still hard to reuse
            2 => 0.0,   // 20..=29: neutral zone
            3 => -4.0,  // 30..=39: reusable for small items
            4 => -6.0,  // 40..=49: quite reusable
            _ => -8.0,  // large residual: flexible bin
        };
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Bonus scaled by how tightly the next item nests in the leftover.
            let tightness = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 + 8.0 * tightness;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 2.0 + ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: reward choosing the tightest fit via base residual term already;
        // slight penalty to spread preference toward best-fit behavior.
        score += 0.0;
    }

    // Compare against fleet average: prefer bins that end up below mean residual (fuller bins).
    if (pr as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default: discourage opening a new bin when open bins can fit.
        score += 30.0;
        // If NO open bin fits (or this is effectively forced), opening is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // If the next item is large and would leave a fresh flexible bin, encourage opening.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // Gap in (0, 10) is essentially dead space (min item size 1..100 unknown,
    // but small gaps rarely reusable) -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when gaps
    // are decent; encourage opening a new bin only if this placement
    // creates dead space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual >= 20 {
        score -= 3.0 * pressure; // good gap: favor reusing open bins
    } else {
        score += 2.0 * pressure; // bad gap: pressure pushes toward new bin
    }

    // Lookahead: if next item fits comfortably in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // dead space for the known next item
    }

    // New empty bin candidate: penalize mildly so it's chosen only when
    // open bins would create dead space or are scarce.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        // If many open bins with large mean residual, prefer reusing them.
        if mean_residual > 25.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement: reward proportional to tightness of the chain fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
        } else {
            // Dead space for the next item: penalize leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.08;
        }
    } else {
        // Last item: only perfect closure matters, otherwise prefer new bin.
        if post_residual > 0 {
            score += 50.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Reward bins tighter than the mean residual (better consolidation).
    score -= (mean_residual - bin_residual as f64) * 2.0;

    // New-bin candidate: baseline so it is chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64).sqrt() * 10.0;
        // In late stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chained_waste = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - chained_waste);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space too small for the lookahead item: penalize proportionally.
        let dead = post_residual as f64;
        let dead_frac = dead / (next_item_size as f64);
        score += 15.0 * dead_frac.min(1.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Reward using bins whose residual is far above the mean (consolidate large holes).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Late in the stream, prefer closing bins tightly (avoid many small leftovers).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * t * waste_frac;

    // New-bin candidate: baseline slightly above good fits, below bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
        // Late stream: be more reluctant to open new bins.
        score += 30.0 * t;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Normalized post-fit waste
    let waste = post_residual as f64 / cap;

    // Base: quadratic waste penalty (dead space is superlinearly bad)
    let mut score = waste * waste * cap;

    // Non-linear coupling: waste penalty grows with stream progress
    // (later in stream, tighter packing matters more)
    score += waste * (1.0 + 3.0 * progress * progress) * 20.0;

    // Reward near-perfect fits with a smooth cubic term in fill ratio
    let fill = item_size as f64 / cap;
    score -= fill * fill * fill * 30.0;

    // Penalize bins whose residual deviates from the mean residual
    // (keep residual diversity low => easier future fits)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Last-chance bonus: smooth exponential-ish reward via squaring
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= (1.0 - slack * slack) * 12.0;
        } else {
            // post-residual can't hold next item: penalize smoothly
            let gap = (nxt - post_residual as f64) / cap;
            score += gap * gap * 20.0;
        }
    }

    // Mild penalty for spreading across many bins early (encourage consolidation)
    score += (open_bins_count as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into 5 classes.
    let class = post_residual * 5 / bin_capacity; // 0..4
    let class_penalty: [f64; 5] = [0.0, 8.0, 14.0, 20.0, 26.0];
    score += class_penalty[class as usize];

    // Modulo structure: residuals near multiples of 10 are more reusable.
    let m = post_residual % 10;
    let m_dist = m.min(10 - m) as f64;
    score += m_dist * 0.6;

    // Reward tight fits (small post residual).
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual == next_item_size) as f64;
        score -= 12.0 + 10.0 * exact;
    } else if next_item_size > post_residual {
        score += 4.0; // dead space for the lookahead
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when residuals are large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.15 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, adjusted by mean residual state.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3 - 20.0 * (mean_residual < 15.0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item can still fit into the post residual,
    // reward keeping this bin useful; if not, penalize the stranded gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps residual profile homogeneous, reducing fragmented gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, allow slightly more exploration of new bins;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // New-bin candidate: make it attractive only when the current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 90.0 } else { 0.0 };
        score = score - bad_fit + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin becomes exactly usable by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here; reward proportional closeness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin; penalize dead space sized near
            // the next item (wasted potential chain).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 15.0 * (1.0 - gap / 20.0);
            }
        }
    } else {
        // Last item: pure tightness matters.
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Favor bins whose residual is above mean (they have more room to spare),
    // penalize dipping below mean residual with this placement.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score += (mean_residual - post_f).min(50.0) * 0.4;
    } else {
        score -= ((post_f - mean_residual).min(50.0)) * 0.2;
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only open bin that fits: strongly avoid opening a new bin.
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin is attractive only if no open bin gives a good fit and the
        // item is large (would leave little usable space in an existing bin).
        let tight_elsewhere = post_residual == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if tight_elsewhere && item_size >= 60 {
            score -= 25.0;
        } else {
            // Prefer reusing existing bins by default.
            score += 30.0;
        }
    }

    // Slight stream-progression term: later in the stream, be more conservative
    // about spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty scaled by wasted chain potential
        score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize placements into bins with residual far from mean (fragmenting outliers),
    // unless it's a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Early stream: discourage new bins unless item is huge.
        // Late stream: allow new bins more readily (future utility lower).
        let new_bin_penalty = 20.0 * (1.0 - progress) * (1.0 - item_frac);
        score += new_bin_penalty;
        // A fresh bin with a large item leaves large residual — slight penalty.
        score += 0.1 * post_residual as f64;
    }

    // Mild pressure against accumulating many open bins with scattered residuals
    score += 0.01 * open_bins_count as f64 * (1.0 - tightness);

    // Time-horizon term: early in the stream, conserve space (favor tight fits more);
    // late in the stream, prioritize just getting items placed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * tightness;

    // Small penalty for very small unusable slivers unless next item can use them
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear shrinkage (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, small residuals are tolerable; late in the stream, waste is costly.
    let coupling = (2.0 * progress - 1.0).powi(2); // 1 at edges, 0 at middle
    score += 12.0 * coupling * norm_pr * norm_pr * cap * 0.01;

    // Reward tight fits smoothly (quadratic in item/binary fit ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last-chance bonus (smoothly scaled by scarcity)
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if post-residual cannot serve next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (nxt / cap) * (1.0 - norm_pr);
        } else {
            score += 3.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Slight preference to spread load when many bins are open vs mean residual
    score += 0.05 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" classes
    // (large enough to host common item sizes) are rewarded; tiny dead space penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space cliff: leftover < 10 is unusable for any item -> strong penalty
    if post_residual < 10 {
        score += 60.0;
    } else {
        // Classify leftover by which item sizes it can still host (harmonic classes)
        // classes: [10,25), [25,50), [50,80), [80,100]
        let class = if post_residual < 25 { 0.0 }
                    else if post_residual < 50 { 1.0 }
                    else if post_residual < 80 { 2.0 }
                    else { 3.0 };
        score -= class * 8.0;

        // Exact modulo structure: leftovers that are multiples of common sizes (10/20/25)
        // tile perfectly with typical streams -> reward divisibility
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 25 == 0 { score -= 5.0; }
        else if post_residual % 20 == 0 { score -= 3.0; }
        else {
            // non-harmonic remainder: penalize proportional to awkwardness
            let r = post_residual % 10;
            score += (5 - r.abs_diff(5)) as f64 * 0.4;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let npr = post_residual - next_item_size;
            // prefer leaving a harmonic next-leftover
            if npr % 10 == 0 { score -= 10.0; }
            score -= (npr as f64) * 0.15;
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, discourage opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln_1p();
        let large_item = item_size as f64 / cap;
        // reward opening a new bin when item is big and existing bins are fragmented
        score -= 18.0 * large_item * (0.5 + frag) + 6.0 * openness * frag;
        // but penalize opening new bins early in the stream
        score += 10.0 * (1.0 - (step_index as f64 / total_items.max(1) as f64));
    }

    // Mild preference for tighter (already-used) bins vs mean residual
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps, scaled by how
    // badly the *next* item is blocked by them.
    let gap_pressure = if post_residual > 0 {
        let blocked = (next_item_size as f64 - post_residual as f64).max(0.0);
        let base = if post_residual < 10 {
            25.0
        } else if post_residual < 20 {
            10.0
        } else if post_residual < 35 {
            3.0
        } else {
            0.0
        };
        base + 0.15 * blocked
    } else {
        -30.0 // exact fill: perfect
    };
    score += gap_pressure;

    // Near-perfect fit reward.
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness reward (best-fit flavor), slightly boosted for large items.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let size_boost = if item_size > 60 { 1.25 } else { 1.0 };
    score -= 10.0 * tightness * size_boost;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: reuse good gaps, push to new bin on bad gaps.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual >= 35 {
        score -= 3.0 * pressure;
    } else if post_residual >= 20 {
        score -= 1.5 * pressure;
    } else {
        score += 2.5 * pressure;
    }

    // Lookahead: reward placements that leave room for the known next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Extra reward when the leftover exactly hosts the next item.
            if post_residual == next_item_size {
                score -= 14.0;
            } else {
                score -= 6.0;
            }
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Two-item lookahead proxy: if next item is large, prefer conserving
    // bins with big residuals for it.
    if next_item_size > 50 && post_residual < next_item_size && post_residual > 40 {
        score += 6.0;
    }

    // New empty bin candidate: chosen only when open bins create dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 25.0 {
            score += 5.0;
        }
        // Late in the stream, opening a fresh bin is cheaper than fragmenting.
        if (step_index as f64) / (total_items.max(1) as f64) > 0.7 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

