    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Penalize dead space relative to capacity, non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 120.0;

    // Tightness relative to the bin's current residual (best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            let pr2 = post_residual as i64 - next_item_size as i64;
            if pr2 <= 10 {
