            }
        } else {
            // Post-residual becomes dead space for the known next item.
            score += 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: log-scaled; reuse good gaps, push new bins for bad gaps.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual >= 20 {
        score -= 4.0 * pressure;
    } else {
        score += 3.0 * pressure;
    }

    // Prefer filling bins that already have low residual (tighter packing).
    score += (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.5;

    // Time horizon: early in stream allow more bins; late, reuse aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (0.5 - progress) * 40.0;

    // New-bin candidate: attractive only for large items or when nothing fits;
    // otherwise discourage, especially when open bins hold big usable gaps.
    if bin_residual == bin_capacity {
        let size_frac = (item_size as f64 / bin_capacity as f64).powi(2);
        score -= 80.0 * size_frac;
        score += 90.0 * (1.0 - size_frac);
        if mean_residual > 25.0 {
            score += 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    score
}

