    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: prefer it only when item is large and no tight fit exists;
    // penalize opening a new bin for small items.
    if bin_residual == bin_capacity {
        score += 15.0 + (bin_capacity as f64 - item_size as f64) * 0.5;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Progress-aware dead-space weighting: later in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Penalize bins whose residual deviates wildly from mean (fragmentation).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

