pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let shape = 1.0 + progress * (1.0 - progress) * 4.0; // hump mid-stream
    score -= shape * prn * prn * cap * 0.5;

    // Penalize large dead space more strongly as stream advances (quartic coupling).
    let dead = (prn * prn * prn * prn) * cap * (0.2 + 0.8 * progress);
    score += dead;

    // Smooth interaction: prefer tight fits when lookahead item fits the post residual.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let tight = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= fits_next * tight * shape * 6.0;
    }

    // Last-chance bonus (smooth ramp via fitting count pressure).
    let pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= pressure * (1.0 + progress) * 4.0;

    // Mild penalty for opening new bins when many bins are open and residual is high.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (2.0 + 6.0 * (1.0 - prn) * shape) + new_bin * (open_bins_count as f64).sqrt();

    // Coupling with mean residual: prefer bins near the mean (smooth deviation term).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot band" it lands in.
    // Small post-residuals are near-perfect fits; large ones are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score += 5.0;
    } else {
        score += 15.0; // large dead space
    }

    // Integer-division harmonic class: post_residual in quarter bands of capacity.
    let quarter = (pr * 4) as f64 / cap;
    score += quarter * 12.0;

    // Modulo logic: residuals divisible by common item sizes are reusable.
    let reusable = [10u32, 20, 25, 50].iter().any(|&d| pr >= d && pr % d == 0);
    if reusable {
        score -= 18.0;
    }

    // Lookahead coupling: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 35.0;
        } else if next_item_size > pr {
            // next item won't fit here; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Prefer bins tighter than average (best-fit style).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - post_residual as f64 / cap);

    // Mild penalty for opening a new bin when others fit (empty-bin candidate).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / (total_items . max (1) as f64) ;
    if post_residual > 0 && post_residual < 12 { score += 28.0 + 12.0 * (1.0 - progress) ; }
    else if post_residual < 22 { score += 9.0 ; }
    if post_residual == 0 { score -= 52.0 ; }
    else if post_residual <= 6 { score -= 18.0 ; }
    // lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - progress) ;
    }
    if next_item_size > 0 && post_residual == next_item_size { score -= 16.0 ; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 { score -= 8.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 14.0 ; // penalize stranded slivers the next item cannot use
    }
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 15.0 * tightness ;
    // combined: large-residual bins with usable lookahead space
    if post_residual > 30 {
        let usable = next_item_size as f64 ;
        if usable > 0.0 && post_residual as f64 >= usable {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64) ;
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0) ;
        }
    }
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    let slack_pressure = (mean_residual / 30.0) . min (2.0) ;
    if post_residual >= 22 { score -= (3.0 + slack_pressure) * pressure ; }
    else { score += 2.0 * pressure ; }
    if post_residual > 12 && post_residual < 22 { score += 6.0 + 5.0 * (1.0 - progress) ; }
    if bin_residual == bin_capacity {
        score += 10.0 ;
        if fitting_bins_count == 0 { score -= 60.0 ; }
        else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 { score -= 18.0 ; }
            if mean_residual > 35.0 { score -= 5.0 ; }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 { score -= 7.0 ; }
            // open a fresh bin when best available fit would strand a large residual
            if mean_residual > 20.0 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
                score -= 8.0 ;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 { score -= 12.0 ; }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 { score -= 10.0 ; }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 { score -= 6.0 ; }
            if fitting_bins_count > 4 && item_size <= 6 { score -= 9.0 ; }
            if progress < 0.3 && mean_residual < 15.0 { score -= 4.0 ; }
        }
        if mean_residual > 25.0 { score += 6.0 ; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 5.0 ; }
        if fitting_bins_count > 2 { score += 14.0 ; }
        if next_item_size > 0 && next_item_size <= bin_capacity { score -= 3.0 ; }
        if item_size > bin_capacity * 3 / 4 { score += 8.0 ; }
        if progress > 0.8 && fitting_bins_count > 0 { score += 5.0 ; }
        if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size . max (1) { score -= 4.0 ; }
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 { score -= 4.0 ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 5.0 ; }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64 ;
            score += 0.35 * gap . ln () . max (0.0) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are worthless; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, reward below
    } else {
        // Dead-space penalty grows quadratically as post_residual shrinks
        // into the "unusable" zone (below typical small item sizes).
        let unusable_threshold = 10.0f64.min(post_residual as f64);
        let dead = (10.0 - unusable_threshold).max(0.0);
        score += 6.0 * dead * dead;
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // and this bin fits reasonably; encourage consolidation.
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 8.0 * pressure * (item_size as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: only attractive if existing residuals are poor
        // for this item (item barely fits nowhere tightly) or stream is late
        // with many bins. Otherwise make new bin expensive.
        let tightness_elsewhere = (mean_residual - item_size as f64).abs();
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_bonus = if tightness_elsewhere > 30.0 { 60.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size as f64 > mean_residual { 40.0 } else { 0.0 }
            + 10.0 * progress;
        score = 100.0 + (bin_capacity as f64) - new_bin_bonus;
    }

    // Lookahead: prefer bins whose post_residual can still host next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
