    let mut score = post_residual as f64;

    // Strong 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this bin (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // reward proportional to how well next item consumes post residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportional to leftover dead space
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    }

    // Reward tight fits of the current item (small post residual is good,
    // but only when not creating unusable slivers).
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill, dead space below min item size
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when open bins could fit, especially late in stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        // but if next item is large and no open bin helps, new bin is less bad
        if next_item_size > bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score -= 10.0;
        }
    }

    score
}

