pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post-residuals are good, but tiny unusable
    // leftovers (< next item) are wasted unless the bin is nearly full.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 * (next_item_size - post_residual) as f64;
        }
        // Reward bins that can also host the lookahead item (chained fit).
        if post_residual >= next_item_size {
            score -= 6.0;
            // Perfect chain: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Reward tight fits (waste ratio).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Relative fit quality: prefer bins where the item fills a large share.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_frac;

    // Global state coupling: if mean residual is high, prefer spreading load
    // into already-open bins rather than opening new ones.
    score -= 0.15 * mean_residual;

    // Many open bins: discourage opening more bins (new-bin candidate gets
    // penalized implicitly since its post_residual is large, but add pressure).
    if bin_residual == bin_capacity {
        score += 3.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheap; late, it is expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Favor denser bins when many bins are open.
        score += 0.5 * open_bins_count as f64 * waste_frac;
    }

    // Time horizon: as stream nears end, minimize leftover slack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
