pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear waste penalty: quadratic in post_residual, scaled by stream progress
    score += 0.9 * pr * pr / cap * (0.5 + progress);

    // Reward tight fits with smooth cubic decay of post_residual
    let fit = 1.0 - pr / cap;
    score -= 25.0 * fit * fit * fit;

    // Penalize bins whose residual is far from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus (smooth): fewer fitting bins -> stronger pull
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 15.0 * scarcity;

    // Lookahead: penalize leaving residual that neither fits nor helps next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Early stream: keep bins flexible (mild penalty on very small residuals)
    score += 10.0 * (1.0 - progress) * (1.0 - fit) * (1.0 - fit);

    // New-bin candidate: smooth preference when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        score += 12.0 * frag * frag - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: classify post_residual into
    // integer-division buckets relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty grows super-linearly for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Class reward: gaps that are "harmonic" (multiples of quarter/eighth)
    // are more likely to absorb future items exactly.
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % eighth == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer division threshold on post_residual class:
    // class = post_residual / 10 (0..10). Middle classes (20..60 residual)
    // are the most reusable; tiny or huge residuals are penalized.
    let class = post_residual / 10;
    match class {
        0 => score += 12.0,          // 0-9: nearly full, dead space risk
        1 => score += 4.0,           // 10-19
        2 | 3 | 4 | 5 => score -= 6.0, // 20-59: sweet spot
        6 | 7 => score -= 2.0,       // 60-79
        _ => {}                      // 80+: nearly empty bin
    }

    // Lookahead: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's gap; penalize proportionally.
            score += 6.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Mild penalty for opening a new bin when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
