pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below half the smallest item are nearly unusable
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: small unusable gap — heavy penalty
            score += 40.0;
        } else if post_residual < 25 {
            score += 12.0;
        } else if post_residual < 50 {
            score += 3.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Penalize leaving a gap that exactly blocks the next item awkwardly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
