    }

    // Penalize leaving tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is poor
    // and residuals across open bins are already large.
    if bin_residual == bin_capacity {
