pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    let mut score = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post residual) mildly.
    // Late stream: penalize dead space much more strongly.
