    // Penalize post residuals that are too small to ever be useful again,
    // modeled smoothly via a bump around the minimum item size.
    let min_item = 1.0f64;
    let unusable = (1.0 - (x * cap / (min_item * 3.0)).min(1.0)).max(0.0);
    score += unusable * 15.0;

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: if next item fits into post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let next_fits = (post_residual as f64 - next_item_size as f64) / cap;
        if next_fits >= 0.0 {
            score -= 10.0 * (1.0 - next_fits).powf(2.0);
        } else {
            score += 5.0 * (-next_fits).powf(1.5).min(3.0);
