    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod small divisors.
    // Residuals divisible by 10 are "clean" classes (easy to fill later);
    // odd/prime residues create dead space -> penalize.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, best possible
    } else {
        let r10 = (post % 10) as f64;
        score += r10 * 1.5; // distance to clean class of 10
        if post % 5 == 0 { score -= 5.0; }
        if post % 2 == 1 { score += 4.0; } // odd residuals pair poorly with even items
        if post % 20 == 0 { score -= 8.0; }
        if post % 25 == 0 { score -= 6.0; }

        // Dead-space threshold: residual below typical small item sizes (1..100)
        // residuals < 15 are nearly unusable -> heavy penalty
        if post < 15 { score += 30.0; }
        else if post < 25 { score += 12.0; }
    }

    // Capacity-fraction coupling: how much of the bin does this item consume?
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 { score -= 25.0; }
    else if fill_frac > 0.6 { score -= 12.0; }
    else if fill_frac < 0.2 { score += 6.0; } // tiny items waste a placement slot

    // Lookahead harmonic: if next item exactly divides or fits post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post { score -= 40.0; }
        else if next_item_size <= post {
            let gap = post - next_item_size;
            if gap % 10 == 0 { score -= 10.0; }
            if gap < 10 { score += 5.0; } // leaves sliver
        } else {
            // next item cannot fit here; if this bin is the only fitting one,
            // we must use it now regardless
            if fitting_bins_count == 1 { score -= 35.0; }
            else { score += 10.0; }
        }
    } else {
        // last item: just minimize waste
        score = post_residual as f64;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer over opening new bin
    if fitting_bins_count == 1 && post > 0 { score -= 20.0; }

    // Stream progression: early on, be willing to open bins (explore);
    // late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 8.0 * (open_bins_count as f64).sqrt().min(6.0);

    // Mean residual anchoring: bins far below mean residual are "ragged";
    // prefer bins whose post_residual is near mean (harmonic alignment).
    let dev = (post as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_existing = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.9 + 40.0 - bad_existing * 60.0
              - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
