    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below the smallest item (1)
    // is impossible, but gaps that no typical item can use are dead space.
    // Penalize "awkward" small gaps nonlinearly.
    if post_residual > 0 {
        // gap smaller than half the smallest plausible item is nearly unusable
        let gap = post_residual as f64;
        if gap < 5.0 {
            score += 60.0 * (1.0 - gap / 5.0); // steep dead-space wall
        }
        // mid-range gaps (5..15) are less reusable than large gaps
        if gap < 15.0 {
            score += 12.0 * (1.0 - gap / 15.0);
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when this bin would leave bad dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 35.0;
        // if current bin residual is large and the item is small, fresh bin wastes nothing
        if bin_residual as f64 - item_size as f64 > 0.5 * item_size as f64 {
            score -= 10.0;
        }
    } else {
        // existing bin: reward using residual efficiently
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // post-residual unusable by next item: mild penalty
        score += 6.0;
    }

    // Stream progression: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 15.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: punish small unusable gaps, stronger early in stream.
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // Tightness coupling: reward filling a bin densely with this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize small post_residual that cannot host the next small item (dead space lookahead).
    if post_residual > 0 && next_item_size > post_residual && next_item_size <= 20 {
        score += 4.0 + 0.3 * (20.0 - next_item_size as f64);
    }
    // Reward post_residual that exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 16.0;
    }
    // Reward near-exact next-item fits leaving tiny residue.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0;
    }
    // gen18: log-scaled gap penalty after next item fits.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score += 0.35 * gap.ln().max(0.0);
    }

    // Open-bin pressure via log, modulated by slack in the system.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Mid-gap penalty: 12..22 residual is wasteful, stronger early.
    if post_residual > 12 && post_residual < 22 {
        score += 6.0 + 5.0 * (1.0 - progress);
    }

    // Large residual handling: reward if next item fits, punish otherwise.
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Lookahead: next item fits the resulting gap -> valuable placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last resort: only fitting bin -> strong preference over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // Large next item: safer to strand it in a fresh bin now.
            if next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            // Small current item with few alternatives: prefer fresh bin.
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            // Pairing potential with next item in a fresh bin.
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            // gen18: residual-relative next-fit bonus for fresh bins.
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            // Tiny items absorb well into existing slack.
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            // Large current item also favors a fresh bin.
            if item_size > 50 {
                score -= 10.0;
            }
        }
        // Harder to open when many open bins already have room.
        if fitting_bins_count > 2 {
            score += 14.0;
        }
        // Late in stream: consolidate, avoid opening bins.
        if mean_residual > 25.0 {
            score += 6.0 + progress * 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if item_size > bin_capacity * 3 / 4 {
            score += 8.0;
        }
        // Late stream consolidation.
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
            score -= 4.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
    } else {
        // gen18: discourage new bins when a near-perfect fit exists elsewhere.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
    }

    score
}

