    let mut score = post_residual as f64;

    // Tight fits are excellent: reward near-exact fills strongly and nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 90.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items
    // (items are 1..=100; residuals below ~12 are nearly dead).
