    // avoiding opening a new bin when the item would fit nowhere else.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Crowding pressure: many open bins -> favor consolidation into
    // already-open bins over spawning more bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 3.0 * crowd * (0.5 + progress);

    // New-bin candidate handling: an empty bin should only win when the fit
