pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual, with non-linear (quadratic) penalty
    // for small residuals that become dead space.
    let mut score = post * (1.0 + 0.35 * norm_post);

    // Smooth stream-progress coupling: as the stream progresses, tighten
    // packing more aggressively (dead space late in the stream is costlier).
    let tighten = 0.4 * progress * (1.0 - progress) * 4.0; // peaks at 0.4 mid-stream
    score += tighten * post * norm_post;

    // Lookahead: if next item fits into the post residual, reward this bin
    // (smooth sigmoid-like coupling on how well the next item fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap); // closer fit -> higher
            score -= 6.0 * fit_quality * (1.0 + progress);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * gap;
        }
    } else {
        // Last item: reward filling as fully as possible.
        score -= 5.0 * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // the current bin would be left with very awkward residual relative to
    // the mean residual across open bins.
    if bin_residual == bin_capacity {
        let awkward = ((mean_residual - post) / cap).abs();
        score += 3.0 + 10.0 * (1.0 - awkward.min(1.0)) * (0.5 + 0.5 * progress);
        // More open bins -> slightly prefer reusing an existing bin instead.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Reusing bins keeps the open set small: mild reward scaled by bin count.
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
        // Reward residual closeness to the mean (keeps bin states homogeneous,
        // smoothing future fits) via smooth coupling.
        let homogeneity = 1.0 - ((bin_residual as f64 - mean_residual) / cap).abs().min(1.0);
        score -= 2.0 * homogeneity;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = step_index as f64 / (total_items . max (1) as f64) ;
    if post_residual > 0 && post_residual < 12 { score += 28.0 + 12.0 * (1.0 - progress) ; }
    else if post_residual < 22 { score += 9.0 ; }
    if post_residual == 0 { score -= 52.0 ; }
    else if post_residual <= 6 { score -= 18.0 ; }
    // lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - progress) ;
    }
    if next_item_size > 0 && post_residual == next_item_size { score -= 16.0 ; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 { score -= 8.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 14.0 ; // penalize stranded slivers the next item cannot use
    }
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 15.0 * tightness ;
    // large-residual region: reward bins that can also host the next item, penalize dead space
    if post_residual > 30 {
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64) ;
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0) ;
        }
    }
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    let slack_pressure = (mean_residual / 30.0) . min (2.0) ;
    if post_residual >= 22 { score -= (3.0 + slack_pressure) * pressure ; }
    else { score += 2.0 * pressure ; }
    if post_residual > 12 && post_residual < 22 { score += 6.0 + 5.0 * (1.0 - progress) ; }
    if bin_residual == bin_capacity {
        score += 10.0 ;
        if fitting_bins_count == 0 { score -= 60.0 ; }
        else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 { score -= 18.0 ; }
            if mean_residual > 35.0 { score -= 5.0 ; }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 { score -= 7.0 ; }
            // open a fresh bin when best available fit would strand a large residual
            if mean_residual > 20.0 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
                score -= 8.0 ;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 { score -= 12.0 ; }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 { score -= 10.0 ; }
            if fitting_bins_count > 4 && item_size <= 6 { score -= 9.0 ; }
        }
        if mean_residual > 25.0 { score += 6.0 ; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 5.0 ; }
        if fitting_bins_count > 2 { score += 14.0 ; }
        if next_item_size > 0 && next_item_size <= bin_capacity { score -= 3.0 ; }
        if item_size > bin_capacity * 3 / 4 { score += 8.0 ; }
        if progress > 0.8 && fitting_bins_count > 0 { score += 5.0 ; }
        // discourage new bins when a near-perfect fit exists elsewhere
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 3.0 ; }
        if progress > 0.9 && fitting_bins_count > 0 { score += 3.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
