pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // are more reusable; penalize awkward residues.
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes of post_residual (mod arithmetic on common size classes)
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr % 10 == 0 { harmonic_bonus += 12.0; }        // multiples of 10 (universal)
    if pr % 20 == 0 { harmonic_bonus += 6.0; }         // multiples of 20
    if pr % 25 == 0 { harmonic_bonus += 5.0; }         // multiples of 25
    if pr % 50 == 0 { harmonic_bonus += 4.0; }
    if pr % 33 == 0 || pr % 34 == 0 { harmonic_bonus += 3.0; }
    if pr >= 80 { harmonic_bonus += 8.0; }             // still fits any item
    else if pr >= 40 { harmonic_bonus += 3.0; }
    else if pr >= 20 { harmonic_bonus += 1.0; }
    else { harmonic_bonus -= 6.0; }                    // tiny dead space
    if pr < 10 { harmonic_bonus -= 10.0; }             // unusable dead space
    score -= harmonic_bonus;

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly: strong reward.
            if next_item_size == pr {
                score -= 40.0;
            } else {
                // Harmonic match: next item's complement also divides nicely.
                let after2 = pr - next_item_size;
                let mut la = 8.0;
                if after2 % 10 == 0 { la += 6.0; }
                if after2 == 0 { la += 25.0; }
                if after2 < 10 && after2 > 0 { la -= 5.0; }
                score -= la;
            }
        } else {
            // Next item won't fit here; mild penalty if this bin would be stranded.
            if pr < 10 { score += 4.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Spread load when many options: prefer tighter fits via post_residual (already).
        score += (fitting_bins_count as f64 - 1.0).sqrt() * 0.5;
    }

    // Prefer bins whose residual deviates from mean (consolidate fullness).
    score += ((bin_residual as f64 - mean_residual) / cap) * 4.0;

    // Early stream: slight preference for packing into existing bins;
    // late stream: keep as-is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bin attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: its post_residual is full capacity.
        // Adjust: discourage new bin if current bins have usable residual.
        if mean_residual > cap * 0.35 && open_bins_count > 0 {
            score += 15.0;
        } else if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
