pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack * 0.1);
        } else {
            // Next item cannot fit in this bin's leftover: penalize dead space,
            // scaled by how far off we are.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Penalize leaving residual that is very small but nonzero (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins that become
    // tighter than average (good consolidation), penalize loose bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current bins
    // are crowded and the item is large relative to the next one.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let crowding = open_bins_count as f64;
        let big_item_bonus = if item_size > 50 { 20.0 } else { 0.0 };
        score += base_penalty + 2.0 * crowding - big_item_bonus;
        // If next item is smaller than current, opening a fresh bin for a big item
        // can be smart: reduce penalty.
        if next_item_size > 0 && next_item_size < item_size {
            score -= 25.0;
        }
    }

    // Slight preference to fill earlier-opened bins as the stream progresses.
    score += 0.01 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
