pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that no future small item (>=1) can use well:
    // dead space is worst when it's small-but-annoying (e.g. 1..20 zone).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += 12.0 * (1.0 - pr / 20.0); // tiny slivers are nearly useless
        } else {
            score -= 3.0; // roomier leftovers can still host future items
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty so we discriminate among multiple fits
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual > next_item_size {
            score -= 8.0; // next item still fits
        } else {
            // next item won't fit here; penalize more if we wasted a big bin
            score += 5.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (use fuller bins first),
    // keeping emptier bins available for larger future items.
    score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0).min(1.0);

    // Time horizon: early in the stream, be conservative about opening new bins
    // (favor filling existing ones); late in the stream, tightness matters most anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress); // early: extra bias toward existing bins

    // Many open bins: discourage spreading; few open bins: new bins are cheaper.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
