pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but its importance grows smoothly with stream progress
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear polynomial coupling: quadratic and cubic terms on normalized residual
    let q = norm_pr * norm_pr;
    let c = q * norm_pr;
    score += 40.0 * q * (1.0 - progress) - 30.0 * c * progress;

    // Tight fits rewarded more as stream progresses (smooth sigmoid-like weight)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (progress + 0.5);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // Last-chance bin: reward strongly with smooth decay in fitting count
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * progress);
    } else {
        score += 5.0 * (fitting_bins_count.min(10) as f64 - 1.0) as f64;
    }

    // Lookahead: reward leaving room close to next item size (smooth kernel)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (-d * d * 50.0).exp() * (1.0 - 0.3 * progress);
    }

    // Slight penalty for too many open bins as stream matures
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: mildly penalized unless residual is large relative to need
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress + 0.1 * item_size as f64;
    }

