pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residual modulo 10 classes.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Residuals divisible by 10 are "harmonic" with typical item granularities -> reward.
    if pr % 10 == 0 {
        score -= 3.0;
    } else if pr % 5 == 0 {
        score -= 1.5;
    } else {
        // Dead-space penalty grows for awkward residuals.
        score += class * 0.15;
    }

    // Very small residuals (< 10) are almost unusable dead space (min item size ~1..10).
    if pr < 10 {
        score += 12.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // Next item fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / pr as f64;
            score -= 8.0 * fill;
            // Harmonic check: post_residual after next placement.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 == 0 { score -= 20.0; }
        } else {
            // Next item won't fit here: mild penalty if this residual is large enough to matter.
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && pr < cap * 0.5 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin has post_residual = cap - item.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when existing bins would leave bad residue.
        // Penalize new bins mildly by default; scale with number of open bins (fragmentation).
        score += 6.0 + 0.5 * open_bins_count as f64;
        // But early in stream, opening bins is cheap.
        score -= 8.0 * (1.0 - progress);
        // If the item is large, a fresh bin guarantees a good future: reward.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's already
    // well-packed; prefer packing it further (best-fit pressure).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    // Late-stream consolidation: as stream ends, prefer filling existing bins tightly.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

