        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space risk).
        if post_residual > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Reward residuals close to mean (keep bins balanced), penalize outliers.
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting large residual space on small items.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste * waste;

    // Prefer filling tight bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.3;

