    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin should be discouraged unless
    // current open bins have low mean residual (all tight) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base cost of opening a new bin, reduced when open bins are tight.
        score += 45.0 - 35.0 * tightness - 10.0 * progress;
        // If item is large, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If open bins can't usefully hold next item either, new bin ok.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 8.0;
        }
    }

    // Mild preference for bins with below-average residual (consolidate slack).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in the stream, avoid opening bins: favor packing into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

