    // Base: penalize leftover space, with superlinear growth (dead space is costly)
    let mut score = pr * (1.0 + 0.9 * fill * fill);

    // Smooth non-linear coupling: leftover-space penalty scales with stream progress
    score += 18.0 * (pr / cap) * (pr / cap) * progress;

    // Reward tight fits (small post_residual relative to item) via smooth saturating term
