        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: bonus if next item fits into the post-residual (smooth decay with gap)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that blocks the next item
        let miss = ((next_item_size as f64 - pr) / cap).min(1.0);
        score += 10.0 * miss * miss;
    }

    // Mild penalty when this bin is far below mean residual (fragmentation risk)
    score += 0.05 * ((mean_residual - pr).abs());

    // New-bin candidate: add a fixed offset so it only wins when open bins are bad
    if bin_residual == bin_capacity {
