        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 5.0; // nothing else fits anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // pairing large items in fresh bins is fine
        }
    }

    // Stream progression: later in the stream, tighten up (avoid leaving residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.15;

    // Mean residual coupling: if average residual is high, favor consolidating here.
    score -= 0.1 * (mean_residual - pr).max(0.0);

    score
}

