    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance: punish small unusable gaps, stronger early in stream.
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // Tightness coupling: reward filling a bin densely with this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize small post_residual that cannot host the next small item (dead space lookahead).
    if post_residual > 0 && next_item_size > post_residual && next_item_size <= 20 {
        score += 4.0 + 0.3 * (20.0 - next_item_size as f64);
    }
    // Reward post_residual that exactly hosts next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 16.0;
    }
    // Reward post_residual that hosts next item with near-perfect leftover.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0;
    }

    // Open-bin pressure via log, modulated by slack in the system.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Mid-range residual penalty, stronger early.
    if post_residual > 12 && post_residual < 22 {
        score += 6.0 + 5.0 * (1.0 - progress);
    }

    // Large post_residual: reward if it can host next item, penalize stranded waste.
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Lookahead: next item fits the resulting gap -> valuable placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last resort: only fitting bin -> strong preference over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            // Small item with few options: fresh bin can anchor a pair.
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            // Perfect pair lookahead in a fresh bin.
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            // Large current item unlikely to pair: fresh bin acceptable.
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            // Fresh bin beats poor fits elsewhere when a near-perfect fit exists.
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
        }
        // Harder to open when many open bins already have room.
        if fitting_bins_count > 2 {
            score += 14.0;
        }
        // Late in stream: consolidate, avoid opening bins.
        if mean_residual > 25.0 {
            score += 6.0 + progress * 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if item_size > bin_capacity * 3 / 4 {
            score += 8.0;
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap.ln().max(0.0);
        }
        // Discourage new bins when a near-perfect fit exists elsewhere.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 3.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Near-perfect fit reward (dead space <= 5 unusable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Chain completion: this placement sets up a perfect second placement.
            score -= 55.0;
        } else if next_item_size < post_residual {
            // Next item still fits after this placement: bonus proportional to
            // how small the resulting double-post residual is.
            let double_post = post_residual - next_item_size;
            score -= 20.0 * (1.0 - double_post as f64 / bin_capacity as f64);
            if double_post <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit in this bin afterwards: penalize creating
            // residual that blocks the lookahead item, unless residual is tiny.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid leaving more space
    // than the average open bin (keeps bin states homogeneous / predictable).
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);
    // Reward being tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the
    // item is large relative to what any residual could absorb, or when the
    // lookahead suggests a big item follows (reserve capacity strategy).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Fresh bin is penalized mildly by default (prefer reusing bins).
        score += 12.0;
        // But if the item is huge (>= 60% capacity), a fresh bin is fine.
        if item_size * 10 >= bin_capacity * 6 {
            score -= 18.0;
        }
        // Late in the stream, consolidation matters more; penalize new bins more.
        if progress > 0.7 {
            score += 8.0;
        }
        // Lookahead: if the next item is large and this item is large, opening
        // a fresh bin now keeps future flexibility.
        if next_item_size >= 50 && item_size >= 50 {
            score -= 10.0;
        }
    }

    // Penalty for leaving residual that is in the "dead zone": too small for
    // the smallest possible item (sizes 1..100, so residual < 1 is impossible,
    // but residual in [1, 9] is nearly unusable given typical item sizes).
    if post_residual >= 1 && post_residual <= 9 {
        score += 10.0;
    }

    // Mild load balancing: when many bins are open, prefer the bin that keeps
    // residual spread reasonable.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
