pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins nearly full.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, modulated by how crowded existing bins are.
        score += 35.0;
        let crowding = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
        } else { 0.0 };
        score -= 25.0 * crowding;
        // Late in stream, prefer closing out open bins rather than starting new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // new bin can host big pairs
        }
    }

    // Prefer bins whose residual is close to the mean (stability), mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for larger residual bins early (keep flexibility), less later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.08 * bin_residual as f64;

    // Reward using many open bins efficiently: penalize leaving many bins idle.
    if fitting_bins_count > 2 && fill_ratio > 0.5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
