pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear base: convex penalty on leftover space (dead space hurts more as it grows)
    let mut score = (post / cap).powf(1.4) * 40.0;

    // Reward tight fills: interaction between fill ratio and progress
    let fill = if resid > 0.0 { item / resid } else { 0.0 };
    score -= fill * fill * (6.0 + 10.0 * t);

    // Smooth coupling of post_residual with stream progress:
    // later in the stream, larger leftovers are penalized more aggressively
    score += (post / cap) * (post / cap) * t * 25.0;

    // Lookahead: penalize leftovers too small for the next item (future dead space)
    if nxt > 0.0 && post > 0.0 {
        let gap = nxt - post;
        if gap > 0.0 {
            score += (gap / cap) * 8.0 * (1.0 + t);
        } else {
            // bonus if next item still fits in this bin
            score -= 3.0 * (1.0 - (post / cap));
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly favor using it
    if fitting_bins_count == 1 && resid < cap {
        score -= 20.0 + 15.0 * t;
    }

    // Penalty for opening a new bin when alternatives exist (smooth in fitting count)
    if resid >= cap {
        let alt = fitting_bins_count as f64;
        score += 12.0 * (1.0 + alt * alt * 0.5);
        // but new-bin penalty softens when open bins are already fragmented
        score -= 6.0 * (mean_residual / cap);
    }

    // Mild preference for bins below mean residual (consolidate fragmented space)
    score += ((resid - mean_residual) / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
