pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable" classes
    // Class A: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Class B: residual divisible by common item granularities (5,10) -> more likely reusable
        let r = post_residual;
        if r % 10 == 0 {
            score -= 12.0;
        } else if r % 5 == 0 {
            score -= 6.0;
        } else {
            score += 4.0;
        }

        // Dead space penalty: small unusable slivers
        if r < 10 {
            score += 20.0;
        } else if r < 20 {
            score += 8.0;
        }

        // Integer-division threshold: can post_residual hold next item (lookahead)?
        if next_item_size > 0 && r >= next_item_size {
            // Harmonic pairing: post_residual / next_item_size ratio classes
            let ratio = r / next_item_size.max(1);
            match ratio {
                1 => score -= 15.0, // exact next fit
                2 => score -= 10.0, // two next items fit
                _ => score -= 4.0,
            }
        } else if next_item_size > 0 {
            // next item cannot follow here: slight penalty, worse if gap is tiny
            let gap = next_item_size.saturating_sub(r);
            score += (gap as f64).min(15.0);
        }
    }

    // Tightness coupling: reward filling bins that are relatively full
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= 25.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if lookahead is huge and no good fit exists, new bin is fine
        if next_item_size > 0 && next_item_size >= item_size && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be more liberal with new bins (explore classes)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (mean_residual / cap).min(1.0);

    // Congestion: many open bins -> prefer consolidating
    score += 0.5 * open_bins_count as f64;

    score
}

