pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // Gaps below the minimum item size (1) are impossible, but very small
    // residuals relative to capacity are "dead" unless they can fit the
    // lookahead item. Use a steep non-linear penalty on tiny residuals.
    let r = post_residual as f64;
    if r > 0.0 && r < 12.0 {
        // tiny gap: nearly unusable -> strong penalty
        score += (12.0 - r) * (12.0 - r) * 4.0;
    } else if r >= 12.0 && r < 25.0 {
        // medium-small gap: mildly awkward
        score += (25.0 - r) * 1.5;
    }

    // Reward when the post residual exactly accommodates the lookahead item
    // (perfect chaining), or when post_residual is zero (perfect fill).
    if post_residual == 0 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap usable by next item -> reward proportionally to tightness
        let tight = (post_residual - next_item_size) as f64;
        score -= 20.0 - tight * 0.5;
    } else if next_item_size > 0 {
        // gap too small for next item: penalize more (future dead space)
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins / leaving many partial bins; consolidate into existing bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // candidate is a brand-new bin: penalize more as open bins grow
        score += pressure * 3.0 + 5.0;
    } else {
        // existing bin: reward slightly as open bins grow (consolidation)
        score -= pressure * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping loose bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early stream: slight preference for keeping bins open flexibly;
    // late stream: push toward filling bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - r / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
