pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the follow-up fit is
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Late in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - 1.0) * 0.5;

    // New-bin candidate: neutral-ish baseline, penalized slightly so it's chosen
    // only when no open bin offers a good (lookahead-aware) fit
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
