pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += 6.0 * tight * tight;

    // Strong reward for nearly-perfect fills (dead space <= 10).
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 3.0;
    }

    // Lookahead: penalize if the next item can't fit in the post residual
    // (this bin becomes dead space for the next step); reward if it fits snugly.
    if next_item_size > 0 {
        if (post_residual as i64) < (next_item_size as i64) {
            // Next item won't fit here; small penalty scaled by how much it misses.
            let miss = next_item_size as f64 - post_residual as f64;
            score += 0.08 * miss;
        } else {
            // Next item fits: reward chain usage, especially near-exact chaining.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 2.5 - 0.05 * chain_waste;
        }
    } else {
        // Last item: strongly prefer filling a bin as much as possible.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 4.0;
        if post_residual <= 30 {
            score -= 2.0;
        }
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about waste.
        score += 0.05 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Penalize the fresh bin mildly; the penalty shrinks as
    // mean residual across open bins shrinks (open bins are nearly full anyway).
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 7.0 - 3.0 * open_pressure;
        // Late in the stream, prefer consolidating into open bins more strongly.
        let late = 2.0 * progress;
        score += (base + late).max(0.5);
        // If no open bin even fits, this penalty is irrelevant (only candidate),
        // so keep it bounded.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Global fragmentation pressure: when mean residual is low (bins nearly full),
    // prefer placements that waste less relative to the average.
    if mean_residual > 0.0 {
        score += 0.02 * (post_residual as f64 - mean_residual);
    }

    // Mild encouragement to use many open bins rather than opening extras early.
    if open_bins_count > 1 && post_residual > 0 {
        score -= 0.01 * open_bins_count as f64;
    }

    score
}

