pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = fitting_bins_count as f64;

    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 20.0;
    score += coupling;

    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 40.0 * tightness * tightness * (0.3 + progress);

    // penalize near-empty usage of a well-populated bin set
    if fitting_bins_count > 1 {
        score -= 8.0 * (1.0 - 1.0 / fit_norm);
    } else {
        score -= 15.0; // last chance bin: strong reward
    }

    // lookahead: prefer bins whose post_residual can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - pr_norm);
    }

    // mean residual deviation penalty (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
