pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes (1..=10) is nearly unusable
    let dead = post_residual.min(20) as f64;
    score += 3.0 * dead;

    // Tight fit bonus: post_residual in "harmonic" classes that pair well with common item sizes
    if post_residual > 0 {
        let pr = post_residual;
        // class 0 mod 10: very reusable
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // classes that match typical item sizes 10..80 range complement
        if (30..=70).contains(&pr) {
            score -= 6.0;
        }
        // tiny residuals 1..=9 are dead space
        if pr <= 9 {
            score += 15.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.5;
    }

    // New-bin candidate handling: only open a new bin when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // prefer new bin if existing bins would leave tiny unusable residue
        let would_be_bad = post_residual <= 9 && post_residual > 0;
        if would_be_bad {
            score -= 40.0;
        } else {
            score += 10.0 + 0.05 * open_bins_count as f64;
        }
    }

    // Prefer fuller bins (low residual before placement)
    score += 0.3 * (bin_capacity as f64 - bin_residual as f64).recip().min(1.0) * 10.0;

    // Early stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Penalize bins far from mean residual (fragmentation spreading)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever hold a future item (min size 1,
    // but gaps below 10 are nearly worthless) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fill is maximally rewarded.
        score -= 100.0;
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading into new bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 3.0;

    // Lookahead: if next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual < 10 {
            // Next item would leave this bin with dead space anyway; slight penalty.
            score += 6.0;
        }
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so that
    // only genuinely bad fits into existing bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 12.0;
        // But if all open bins would be left with unusable dead space, new bin wins.
        if post_residual_of_worst(bin_residual, item_size) {
            score -= 50.0;
        }
    }

    // Mild preference for bins whose residual is below the mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

fn post_residual_of_worst(bin_residual: u32, item_size: u32) -> bool {
    let pr = bin_residual - item_size;
    pr > 0 && pr < 10
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
