pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial emphasis on small residuals (good fits)
    let mut score = pr.powf(1.35);

    // Non-linear coupling of post-residual with stream progress:
    // later in the stream, dead space matters more (harder to compensate)
    let progress_coupling = 1.0 + 0.8 * progress * (norm_pr * (1.0 - norm_pr) * 4.0);
    score *= progress_coupling;

    // Smooth penalty for very small post-residuals that are still nonzero (dead space)
    let dead = (1.0 - norm_pr).powi(3);
    score -= 6.0 * dead * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins whose residual is close to the item (smooth fit term)
    let fit_quality = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 8.0 * fit_quality * fit_quality;

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack).max(0.0) * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 4.0 * gap * (1.0 - gap);
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * (open_bins_count as f64).powf(0.9) * (1.0 - progress);

    // New-bin candidate: make it attractive only when residuals in open bins are large
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = pr.powf(1.35) * (1.0 + 0.6 * mean_norm) + 3.0 * (1.0 - progress);
