            score -= 5.0; // still very reusable
        } else {
            score -= 10.0; // large residual keeps options open
        }

        // Harmonic coupling: can next_item_size fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // lookahead fits: reward proportionally to how snug
                let slack = (post_residual - next_item_size) as f64;
                if slack == 0.0 {
                    score -= 200.0; // chain of perfect fits
                } else if slack < 10.0 {
                    score -= 40.0;
                } else {
                    score -= 5.0;
                }
            } else {
                // next item cannot use this residual: penalize by overshoot size
                let overshoot = (next_item_size - post_residual) as f64;
                score += 0.5 * overshoot;
            }
