            score -= 2.0;
        }
        // Penalize residuals in "dead zones": values that few sizes (1..100)
        // can combine with — i.e., pr in (50,60) exclusive of nice numbers.
        if pr > 50 && pr < 60 && pr % 10 != 0 {
            score += 6.0;
        }

        // Integer-division threshold: residual that can host at least a
        // medium item (>= 30) is valuable.
        if pr / 30 >= 1 && next_item_size > 0 && next_item_size > pr {
            score += 3.0; // wasted medium-capable space
        }
    }

