            // big next item that won't fit leftovers anywhere: new bin is fine
            if next_item_size > bin_capacity / 2 {
                score -= 20.0;
            }
            // item + next fills a fresh bin exactly
            if item_size + next_item_size == bin_capacity {
                score -= 14.0;
            }
            // large item dominating a bin: fresh bin acceptable
            if item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            // many alternatives exist: strongly discourage new bin
            if fitting_bins_count > 2 {
                score += 18.0;
            }
            if mean_residual > 25.0 {
                score += 8.0;
            }
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into tight ones
    if open_bins_count > 3 && fitting_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln();
        if post_residual >= next_item_size.max(1) {
            score -= 4.0 * pressure;
        } else {
            score += 3.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: post residuals that are too small for typical future items.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
