    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in stream, prefer packing into existing bins less aggressively
    // (keep flexibility); later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0 * (1.0 - fit_ratio);
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64 / 20.0).min(1.0);

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if mean_residual > item_size as f64 {
        score -= (mean_residual - item_size as f64) * 0.08;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative
    // to residual or existing fits are poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 18.0
            - (item_size as f64 / bin_capacity as f64) * 20.0
            + (fitting_bins_count as f64) * 6.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // new bin gives room for the next item
        }
    }

    // Mild penalty for wasting a large residual on a small item.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

