pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // non-linear coupling with stream progress: later in stream, value tight fits more
    let prog_coupling = 2.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= prog_coupling * item;

    // penalize dead space relative to mean residual, smooth quadratic
    let dead = (pr - mean_residual).abs();
    score += 0.3 * dead * dead / cap;

    // last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // lookahead: if next item fits post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // discourage spreading across too many open bins early
    score += 0.5 * open_bins_count as f64 * progress * progress;

    // new-bin candidate: prefer it only when item is large relative to residual elsewhere
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) * (item / cap);
        score += 10.0 * progress;
    }

    score
}

