        score += 25.0 * (1.0 - waste.min(1.0));
    }

    // Penalize leaving residual far from mean (fragmenting the pool).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            1.0
        };
        // Opening a new bin wastes the remaining capacity of existing bins;
        // penalize proportionally to how much capacity would be stranded.
        let stranded = mean_residual * open_bins_count as f64;
        score += 20.0 + stranded * 0.3 - desperation * 0.0;
        // Allow new bin when stream is early and mean residual is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
    }

    // Slight preference to fill bins with more residual when many bins open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

