pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1), used for a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that cannot fit the smallest plausible item (1..100 range).
    if post_residual > 0 {
        score += 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).exp();
    }

    // Lookahead: if the next item fits into the post-residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 10.0 * (post_residual as f64 - next_item_size as f64).recip();
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual is stranded relative to the next item; mild penalty.
        score += 6.0;
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: prefer using bins whose residual deviates from the mean
    // (consolidate fragmented space into balanced bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 * dev / (bin_capacity as f64);

    // Crowding pressure: many open bins -> favor filling existing ones.
    let crowd = (open_bins_count as f64).ln() + 1.0;
    score += 8.0 / crowd;

    // Time horizon: early on, exploration (opening new bins) is cheaper; late,
    // aggressively consolidate to avoid a trailing tail of half-empty bins.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (35.0 + 60.0 * progress);

    // A new bin is attractive for very large items that would leave tiny fragments elsewhere.
    if bin_residual == bin_capacity {
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

