pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and item footprint
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / cap;                    // how much this item fills
    let post_norm = post_residual as f64 / cap;           // normalized dead space after placement
    let res_norm = bin_residual as f64 / cap;             // normalized space before placement

    // Non-linear polynomial coupling: dead space penalty grows super-linearly
    // with stream progress (later in the stream, wasted space matters more).
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 18.0 * post_norm * post_norm * (0.35 + 1.65 * prog2)
           + 10.0 * post_norm * post_norm * post_norm * (0.2 + 1.3 * prog3);

    // Smooth reward for tight fits: high fill ratio on a small residual is good.
    // Interaction term coupling item fill with how full the bin already is.
    let tightness = fill * (1.0 - post_norm);
    score -= 14.0 * tightness * (0.4 + 0.9 * prog2);

    // Penalize leaving a residual that is a poor match for typical future items:
    // smooth "awkward gap" term — residuals near the middle of the range are
    // the most reusable, tiny residuals are dead space, huge residuals mean
    // we under-filled. Use smooth cos-based bump on post_norm.
    let awkward = 1.0 - (4.0 * (post_norm - 0.3) * (post_norm - 0.3)).tanh().abs();
    score += 6.0 * awkward * post_norm * (0.3 + 1.2 * progress);

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post dead space is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0 * (1.0 - post_norm * post_norm) * (0.5 + 1.0 * prog2);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item barely misses, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = nx - post_norm;
        if gap <= 0.0 && gap > -0.35 {
            score -= 7.0 * (1.0 + gap.abs()) * (0.5 + 1.0 * prog2);
        } else if gap > 0.0 && gap < 0.15 {
            score += 5.0 * (0.15 - gap) * (0.5 + 1.0 * prog2);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream:
    // encourage consolidation relative to mean residual.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score += 4.0 * (rel - 1.0) * (1.0 - (rel - 1.0)) * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral baseline with smooth early-stream preference
    // so a fresh bin wins when all open fits are poor.
    if bin_residual == bin_capacity {
        score = 0.55 * cap * (1.0 - 0.55 * prog2) + 12.0 * post_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
