pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    // Residues near 0 (divisible by 10) are more likely to be exactly filled by
    // future items in the 1..=100 integer stream -> reward them (subtract).
    let post_class = post_residual % 10;
    let class_reward = match post_class {
        0 => 12.0,
        5 => 6.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };
    score -= class_reward;

    // Penalize small-but-not-zero post_residual (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 - (post_residual as f64);
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic coupling with next item: if the next item exactly fits the
    // post_residual, this is a chained perfect fill -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            if nxt_class == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover likely stranded.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a fresh bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when current
    // bin would leave badly fragmented residue.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Fraction-of-capacity thresholds on post_residual (integer division).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0; // roomy remainder, still flexible
    } else if post_residual >= quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 4.0; // cramped remainder
    }

    // Late in the stream, consolidate more aggressively: favor tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Many open bins: prefer bins below mean residual (balancing harmonic classes).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
