pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize tiny unusable gaps superlinearly (gap below 10 is pure waste).
        if post_residual < 10 {
            score += (10.0 - dead) * 12.0;
        } else {
            // Smooth penalty that grows as the gap shrinks toward the dead zone.
            score += (10.0 / dead) * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (waste ratio view).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and penalize opening yet another one.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only when current bins are mostly full
        // or the item would leave a terrible gap elsewhere.
        score += 20.0 + pressure * 15.0 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    } else {
        score += pressure * 2.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // reward leaving that gap; if the next item cannot fit the gap anyway,
    // the gap is dead space, so penalize harder.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            score += (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Late in the stream, be more conservative: consolidate into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
