pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 6 {
        score -= 20.0;
    }

    // 2-step lookahead with progress-scaled weights
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 260.0 - slack * 1.2;
            // near-exact chain: extra reward
            if slack <= 2.0 {
                score -= 30.0 * (1.0 - progress * 0.5);
            } else {
                // logarithmic gap penalty: larger leftover after chain is worse
                score += 0.35 * slack.ln().max(0.0);
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else {
        score = post_residual as f64 * 3.0;
        if bin_residual == bin_capacity {
            score += 200.0; // never open a bin for the last item
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // Best-fit flavor with tightness coupling
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Awkward dead zone, scaled by progress (early stream more tolerant)
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + 25.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 18.0 + 10.0 * (1.0 - progress);
    } else if post_residual > 30 {
        // large leftover: penalize unless it chains with next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 70.0;
    }

    // NEW-BIN CANDIDATE handling: default penalty, conditional relief
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            // big next item that won't fit leftovers anywhere: new bin is fine
            if next_item_size > bin_capacity / 2 {
                score -= 20.0;
            }
            // item + next fills a fresh bin exactly
            if item_size + next_item_size == bin_capacity {
                score -= 16.0;
            }
            // large item dominating a bin: fresh bin acceptable
            if item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            // small item with few alternatives: fresh bin acceptable
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            // many alternatives exist: strongly discourage new bin
            if fitting_bins_count > 2 {
                score += 16.0;
            }
            if mean_residual > 25.0 {
                score += 8.0;
            }
            // near-perfect chain available elsewhere: avoid new bin
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into tight ones
    if open_bins_count > 3 && fitting_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln();
        let slack_pressure = (mean_residual / 30.0).min(2.0);
        if post_residual >= next_item_size.max(1) {
            score -= (3.0 + slack_pressure) * pressure;
        } else {
            score += 3.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
