    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it's genuinely attractive
    // (e.g., no open bin fits well or stream is early).
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 15.0; // big item: fresh bin is fine
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
            if slack <= 4.0 {
                score -= 9.0;
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 520.0;
        }
        if post_residual > next_item_size && post_residual - next_item_size <= 4 {
            score -= 7.0;
        }
        // gen36: logarithmic penalty for large gaps beyond next item
        if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap.ln().max(0.0);
        }
    } else {
        score = post_residual as f64 * 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Best-fit flavor
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Awkward residual zone
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }
    if post_residual > 12 && post_residual < 22 {
        score += 6.0 + 5.0 * (1.0 - progress);
    }

    // Pressure-based consolidation
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Large residual handling
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 60.0;
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            // gen36: discourage new bins when a near-perfect chain fit exists elsewhere
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 3.0;
            }
            // gen36: penalize new bins when mean residual is large enough to absorb small items
            if mean_residual >= item_size as f64 + 8.0 {
                score += 8.0;
            }
            // gen36: discourage new bins late in the stream when any bin fits tightly
            if progress > 0.7 && fitting_bins_count >= 1 && post_residual <= 10 {
                score += 6.0;
            }
            // gen36: exact chain match elsewhere strongly favors existing bins
            if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 {
                score -= 4.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // gen36: reward bins whose post-residual matches next item exactly
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0;
        }
        // gen36: gentle penalty for leaving medium dead zones relative to mean residual
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
        // gen36: extra reward for very tight leftover fits on existing bins
        if post_residual > 0 && post_residual <= 3 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Assume items are >= 1..=100; residual below the smallest plausible
    // next item (use min(item_size, next_item_size if >0) as a proxy) is waste.
    let smallest_next = if next_item_size > 0 { next_item_size.min(item_size).max(1) } else { item_size.min(1).max(1) };
    if post_residual > 0 && post_residual < smallest_next {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual exactly (or nearly)
    // accommodates the next item — enables chaining.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by overflow gap.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let mut new_bin_cost = 15.0;
        // Early in the stream or when open bins are crowded, new bins are cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 8.0 * (1.0 - progress);
        // If mean residual across open bins is small (bins are full), opening is fine.
        new_bin_cost -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_cost += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Large items relative to capacity benefit from a fresh bin.
        new_bin_cost -= 6.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_cost;
    } else {
        // Mild penalty for using a very full bin when alternatives exist,
        // but reward fragmenting bins that are nearly empty anyway.
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fill_ratio;
    }

    // Prefer spreading load when many bins are open (keeps options alive),
    // but only mildly.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Time-horizon term: later in the stream, consolidation matters more —
    // penalize residual waste harder as we approach the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

