pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, modulated by smooth progress polynomial
    let prog_poly = 0.5 + 2.0 * progress * (1.0 - progress) + 1.5 * progress * progress;
    let mut score = pr * prog_poly;

    // Non-linear penalty for small dead space (waste), smoothed
    let dead = (norm_pr - 0.05).max(0.0);
    score -= 30.0 * (1.0 - dead).powi(3) * (1.0 - progress);

    // Perfect fit reward, decaying with progress
    if post_residual == 0 {
        score -= 50.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving space for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = pr >= nx;
        let coupling = (pr - nx).abs() / cap;
        score += 10.0 * (1.0 - coupling).powi(2) * if fits_next { -1.0 } else { 1.0 };
        if !fits_next && pr < nx && pr > 0 {
            score += 25.0 * (1.0 - pr / nx);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / cap) > 0.5;
        score += if poor_fit { -15.0 * (1.0 - progress) } else { 25.0 + 10.0 * progress };
    }

    // Mean residual divergence penalty
    score += 0.5 * (pr - mean_residual).abs();

    score
}

