pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable.
    let class_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect closure is always great
    } else if post_residual % 50 == 0 {
        -18.0
    } else if post_residual % 25 == 0 {
        -12.0
    } else if post_residual % 20 == 0 {
        -10.0
    } else if post_residual % 10 == 0 {
        -7.0
    } else {
        0.0
    };
    score += class_bonus;

    // Harmonic coupling with lookahead: if the next item divides the
    // post-residual exactly, this bin is a perfect pair.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 20.0;
        } else if post_residual - next_item_size <= 10 {
            // next item leaves near-closure
            score -= 8.0;
        } else {
            // next item fits but leaves awkward residue
            let leftover = (post_residual - next_item_size) % 10;
            score += leftover as f64 * 0.8;
        }
    } else if next_item_size > post_residual {
        // post-residual too small for the next item: dead space unless tiny
        if post_residual < 10 {
            score -= 5.0; // negligible dead space
        } else {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current fit
    // is poor (large awkward residual) and plenty of bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 40.0 && (post_residual % 10 != 0);
        if poor_fit && open_bins_count > 2 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 20.0; // discourage gratuitous new bins
        }
    }

    // Mild penalty for deviating from the mean residual (keeps bins balanced).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // Slight preference for tight fits relative to capacity fractions.
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= fill * 5.0;

    score
}

