pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size) are worst.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 80.0; // tiny unusable dead space: heavily penalize
    } else {
        // Usable gap: reward tight fits mildly, penalize large waste slightly
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 20.0;
    }

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins whose residual is close to mean residual (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 { score -= 40.0; } else if gap < 10 { score += 30.0; }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 10.0; // next item can't use this dead space either
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

