    // Penalize dead space: residuals too small for any future item (min size 1,
    // but realistically small slivers are waste). Use a soft threshold around
    // a fraction of capacity.
    let dead_threshold = bin_capacity as f64 * 0.08;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // reward leaving room for the next item proportionally to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; mild penalty scaled by wasted potential
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item fits poorly everywhere else. Penalize the fresh bin mildly,
    // unless it's the very first bin (nothing open yet).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        } else {
            score += 18.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Time horizon: early in the stream, be more conservative about filling
    // bins tightly (keep flexibility); late in the stream, prioritize tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

