    // there is slack in the system — prefer placements that reduce variance,
    // i.e., prefer bins whose residual is far from the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // Prefer using bins with less residual when many bins are open
    // (consolidation pressure).
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

