pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    let pr = post_residual;
    let class = pr % 10; // residue class mod 10
    let tier = pr / 25;  // coarse tier of leftover space

    // Penalize leftover space in "dead" classes (small, hard-to-fill residues)
    let dead_penalty = match class {
        0 => -6.0,          // perfectly divisible leftover is great
        1 | 2 => 8.0,       // tiny slivers are dead space
        3 | 4 => 3.0,
        5 => -2.0,          // multiples of 5 pair well with typical items
        6 | 7 => 4.0,
        8 | 9 => 5.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Tier-based reward: encourage leaving large, reusable residuals
    score -= match tier {
        0 => 4.0,   // post_residual < 25: nearly full bin, good
        1 => 0.0,
        2 => -1.0,
        _ => -2.5,  // large leftover: keep flexibility
    };

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect harmonic match: next item exactly fills or nearly fills
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 20.0; // perfect chaining
            } else if gap % 10 == 0 {
                score -= 10.0; // clean harmonic chain
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit: penalize more if the miss is small (wasted potential)
            let miss = next_item_size - pr;
            score += (miss as f64).min(30.0) * 0.3;
