    let progress = step_index as f64 / (total_items . max (1) as f64) ;
    if post_residual > 0 && post_residual < 12 { score += 28.0 + 12.0 * (1.0 - progress) ; }
    else if post_residual < 22 { score += 9.0 ; }
    if post_residual == 0 { score -= 52.0 ; }
    else if post_residual <= 6 { score -= 18.0 ; }
    // lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - progress) ;
    }
    if next_item_size > 0 && post_residual == next_item_size { score -= 20.0 ; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 { score -= 10.0 ; }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 14.0 ; // penalize stranded slivers the next item cannot use
    }
    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 15.0 * tightness ;
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    let slack_pressure = (mean_residual / 30.0) . min (2.0) ;
    if post_residual >= 22 { score -= (3.0 + slack_pressure) * pressure ; }
    else { score += 2.0 * pressure ; }
    if post_residual > 12 && post_residual < 22 { score += 6.0 + 5.0 * (1.0 - progress) ; }
    // large-residual quality assessment: usable leftover for next item vs dead space
    if post_residual > 30 {
        let usable = next_item_size as f64 ;
        if usable > 0.0 && post_residual as f64 >= usable {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64) ;
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0) ;
        }
    }
    // dead-space ratio coupling: fraction of the bin wasted after placement
    let dead_ratio = post_residual as f64 / bin_capacity . max (1) as f64 ;
    if dead_ratio > 0.5 { score += 8.0 * (dead_ratio - 0.5) * (1.0 - progress) ; }
    else if dead_ratio < 0.15 { score -= 6.0 * (0.15 - dead_ratio) * 10.0 ; }
    // two-item lookahead: bin should be able to host item then next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size ;
        if chain_slack == 0 { score -= 6.0 ; }
        else if chain_slack <= 8 { score -= 4.0 * (1.0 - progress) ; }
    }
    if bin_residual == bin_capacity {
        score += 10.0 ;
        if fitting_bins_count == 0 { score -= 60.0 ; }
        else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 { score -= 18.0 ; }
            if mean_residual > 35.0 { score -= 5.0 ; }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 { score -= 7.0 ; }
            // open a fresh bin when best available fit would strand a large residual
            if mean_residual > 20.0 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
                score -= 10.0 ;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 { score -= 12.0 ; }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 { score -= 10.0 ; }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 { score -= 6.0 ; }
            if fitting_bins_count > 4 && item_size <= 6 { score -= 9.0 ; }
            if progress < 0.3 && mean_residual < 15.0 { score -= 4.0 ; }
            // new-bin trigger: if the best existing fit leaves a large unusable gap, prefer fresh bin
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > 15 {
                score -= 12.0 ;
            }
        }
        if mean_residual > 25.0 { score += 6.0 ; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 5.0 ; }
        if fitting_bins_count > 2 { score += 14.0 ; }
        if next_item_size > 0 && next_item_size <= bin_capacity { score -= 3.0 ; }
        if item_size > bin_capacity * 3 / 4 { score += 8.0 ; }
        if progress > 0.8 && fitting_bins_count > 0 { score += 5.0 ; }
        if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size . max (1) { score -= 4.0 ; }
        if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 { score -= 4.0 ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 5.0 ; }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64 ;
            score += 0.35 * gap . ln () . max (0.0) ;
        }
        // discourage new bins when a near-perfect fit exists elsewhere
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 5.0 ; }
        if progress > 0.9 && fitting_bins_count > 0 { score += 3.0 ; }
    } else {
        // existing-bin refinements: reward near-perfect consumption of residuals
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 7.0 ; }
        if post_residual > 0 && post_residual < next_item_size . max (1) && post_residual > 20 { score += 6.0 ; }
        // reward bins whose residual after placement exactly matches next item modulo small slack
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5 && fitting_bins_count > 3 {
            score -= 3.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, penalized smoothly by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear coupling: small post-residuals are much more valuable late
    score -= 40.0 * (1.0 - pr_norm).powi(3) * (0.5 + 0.5 * progress);

    // Dead-space penalty: residuals too small for typical items (smooth kernel)
    let dead = (pr_norm - 0.12).powi(2);
    score += 30.0 * (-dead * 120.0).exp() * (0.4 + 0.6 * progress);

    // Lookahead synergy: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs() / cap;
        score -= 25.0 * (-diff * diff * 200.0).exp();
        // Penalize wasting space the next item could have used in a fresh bin
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt.max(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.15 * open_bins_count as f64 * (pr_norm);

    // Encourage new-bin usage early for large items (leave open bins for small items)
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 20.0 * big * (1.0 - progress) - 10.0 * progress;
    }

    // Mean-residual deviation: prefer bins whose residual deviates from mean
    let dev = (pr - mean_residual) / cap;
    score -= 5.0 * dev * dev;

    score
}

