pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins whose post-residual falls into
    // "small and reusable" classes are strongly preferred.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: best possible outcome.
        score -= 1000.0;
    } else if pr <= 10 {
        // Tiny leftover: nearly perfect, still excellent.
        score -= 500.0 + (10 - pr) as f64 * 10.0;
    } else if pr <= 30 {
        // Medium leftover: usefulness depends on whether it can host
        // the next item (harmonic pairing with lookahead).
        if next_item_size > 0 && next_item_size <= pr {
            score -= 250.0;
        } else {
            score += 50.0;
        }
    } else {
        // Large leftover: wasteful placement unless bin was nearly empty anyway.
        score += 100.0;
    }

    // Modulo-10 harmonic classes: leftovers matching common item-size
    // residues (multiples of 10) are more likely reusable.
    if pr > 0 && pr % 10 == 0 {
        score -= 40.0;
    }
    // Odd leftovers are dead space magnets.
    if pr % 2 == 1 && pr > 0 {
        score += 15.0;
    }

    // Integer-division thresholds: bin_residual class relative to capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if bin_residual > half {
        // Bin still roomy; using it for a big item is fine.
        score -= 20.0;
    } else if bin_residual > quarter {
        // Tight fit zone: encourage filling toward zero residual.
        score -= 10.0;
    } else {
        // Bin nearly full: only attractive if we close it out exactly.
        if pr > 0 {
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // item is large and no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 300.0;
        // Large items waste less in a fresh bin.
        if item_size >= half {
            score -= 250.0;
        }
        // If few bins fit the item, new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below
    // average (concentrate waste), penalize above-average-residual bins.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Lookahead synergy: if next item fits exactly in post_residual,
    // reward strongly (harmonic chain).
    if next_item_size > 0 && next_item_size == pr {
        score -= 300.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
