pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: dead space penalty scaled to next item size.
        score += 0.15 * next_item_size as f64;
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Mild reward for filling existing bins tightly relative to mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Prefer placing larger items into emptier bins (best-fit against big items).
    score += 0.05 * (bin_residual - item_size) as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

