    // Fractional fill achieved by this placement
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly (non-linearly)
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to be useful later:
    // residuals below ~10 are nearly unusable, residuals 10..=30 are risky.
    let dead = post_residual as f64;
    if dead < 10.0 {
        score += 8.0; // tiny sliver: wasted but bin is "closed" — acceptable
        score -= 12.0; // but perfect closure is good
    } else if dead < 30.0 {
        score += (30.0 - dead) * 0.35; // risky gap zone
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item cannot follow here: mild penalty proportional to overflow
        score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream and when many bins are already open but mean residual is high.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 25.0 + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0; // existing space could absorb the item
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += new_bin_penalty;
        } else {
            score -= 5.0; // no alternative: new bin is fine
