    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Slight time-horizon adaptation: later in the stream, prefer tighter packing
    score -= 6.0 * progress * fill;

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

