            if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 {
                score -= 4.0;
            }
            // if any open bin leaves a near-perfect chain residual, strongly block new bin
            if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
                score += 9.0;
            }
            // dead-space ratio guard — block new bins when mean residual already exceeds half a bin
            if mean_residual > bin_capacity as f64 * 0.5 {
                score += 10.0;
            }
            // gen43: block new bins mid-stream when total wasted space is still recoverable
            if progress < 0.6 && mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 3 {
                score += 7.0;
            }
            // gen43: allow new bins for items that would leave a perfectly chainable residual
            if next_item_size > 0 && item_size + next_item_size == bin_capacity {
                score -= 8.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // reward bins whose post-residual matches next item exactly
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0;
        }
        // gentle penalty for leaving medium dead zones relative to mean residual
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
        // extra reward for very tight leftover fits on existing bins
        if post_residual > 0 && post_residual <= 3 {
            score -= 4.0;
        }
        // prefer bins whose post-residual stays below mean residual (compact packing)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 {
            score -= 3.0;
        }
        // gen43: stronger reward for bins that remain chainable across the next two slots
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals nonlinearly (dead space waste).
    let post = post_residual as f64;
    score += 0.35 * (post / bin_capacity as f64) * (post / bin_capacity as f64) * bin_capacity as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post {
            let slack = post - ns;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual as i64 - next_item_size as i64) == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; mild penalty if we leave awkward gap.
            score += 3.0 * (ns - post) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Time horizon: early in stream, prefer consolidating (favor open bins);
    // late in stream, waste tolerance rises.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Many open bins with high mean residual: discourage adding to scattered state.
    if open_bins_count > 2 {
        let spread = (mean_residual - post).abs();
        score += 0.05 * spread * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= post && (post - next_item_size as f64) < 10.0 {
            score -= 12.0; // fresh bin pairs perfectly with next item
        }
    }

    // Small bonus for exact fill.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit reward (strengthened)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
            if slack <= 4.0 {
                score -= 9.0;
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 520.0;
        }
        if post_residual > next_item_size && post_residual - next_item_size <= 4 {
            score -= 7.0;
        }
        if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap.ln().max(0.0);
        }
        // gen39: reward bins that can absorb BOTH current and next item exactly
        if post_residual >= next_item_size
            && item_size as f64 + next_item_size as f64 <= bin_capacity as f64
            && post_residual <= bin_capacity / 2
        {
            score -= 12.0;
        }
        // gen43: reward bins whose post-residual equals next_item_size exactly (borrowed from best)
        if post_residual == next_item_size {
            score -= 16.0;
        }
        // gen43: stronger near-exact chain reward
        if post_residual > next_item_size && post_residual - next_item_size <= 4 {
            score -= 8.0;
        }
    } else {
        score = post_residual as f64 * 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Best-fit flavor
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Awkward residual zone
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }
    if post_residual > 12 && post_residual < 22 {
