            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 3.0;
            }
            if mean_residual >= item_size as f64 + 8.0 {
                score += 8.0;
            }
            if progress > 0.7 && fitting_bins_count >= 1 && post_residual <= 10 {
                score += 6.0;
            }
            if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 {
                score -= 4.0;
            }
            if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
                score += 9.0;
            }
            if mean_residual > bin_capacity as f64 * 0.5 {
                score += 10.0;
            }
            // gen43: stronger new-bin penalty when mean residual can absorb the item
            if mean_residual >= item_size as f64 + 4.0 && fitting_bins_count > 0 {
                score += 12.0;
            }
            // gen43: block new bins late when any fitting bin leaves <= 8 dead space
            if progress > 0.5 && fitting_bins_count > 0 && post_residual > 0 && post_residual <= 8 {
                score += 14.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0;
        }
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 4.0;
        }
        // gen39: prefer bins whose post-residual stays below mean residual (compact packing)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 {
            score -= 3.0;
        }
        // gen43: dead-space ratio guard on existing bins — penalize bins leaving more than half capacity
        if post_residual > bin_capacity / 2 {
            score += 5.0;
        }
        // gen43: reward near-exact chain fits on existing bins more strongly
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear coupling: post-residual value modulated by stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;
    // Penalize near-full waste lightly as stream advances
    score -= (1.0 - norm_pr).powi(3) * (20.0 + 30.0 * progress);
    // Reward tight fits more strongly late in the stream
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * (10.0 + 25.0 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }
    // Lookahead: favor bins leaving room for next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap * (1.0 - progress);
    }
    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }
    // Mean residual dispersion coupling
    score += 0.05 * (mean_residual - pr).abs();
    score
}

