pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual by capacity fractions
    let cap_f = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in low harmonic classes gets bonuses
    match post_residual {
        0 => score -= 50.0,                       // perfect fill
        r if r <= eighth => score -= 25.0,        // near-perfect
        r if r <= quarter => score -= 10.0,       // good
        r if r <= bin_capacity / 2 => score -= 3.0, // moderate
        _ => { score += 5.0; }                    // wasteful, more than half left
    }

    // Modulo-10 class of post_residual: small remainders (1..=9) are dead space
    let rem10 = post_residual % 10;
    if rem10 > 0 && rem10 < 5 {
        score += rem10 as f64 * 1.5; // penalize awkward small dead space
    } else if rem10 == 0 && post_residual > 0 {
        score -= 4.0; // round-class residual is reusable
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: strong reward
            score -= (post_residual - next_item_size) as f64 * 0.6 + 8.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; penalize leaving medium residual that traps nothing
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 6.0; // near-miss: wasted opportunity
            }
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, worse than tight fits
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + item_size as f64 * 0.3;
        // early stream: opening bins is cheap; late stream: prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // if many open bins, discourage new bin
        score += open_bins_count as f64 * 1.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

