                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            // discourage new bins when a near-perfect chain fit exists elsewhere
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 3.0;
            }
            // penalize new bins when mean residual is large enough to absorb small items
            if mean_residual >= item_size as f64 + 8.0 {
                score += 8.0;
            }
            // discourage new bins late in the stream when any bin fits tightly
            if progress > 0.7 && fitting_bins_count >= 1 && post_residual <= 10 {
                score += 6.0;
            }
            // exact chain match elsewhere strongly favors existing bins
            if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 {
                score -= 4.0;
            }
            // gen39: if any open bin leaves a near-perfect chain residual, strongly block new bin
            if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
                score += 9.0;
            }
            // gen39: dead-space ratio guard — block new bins when mean residual already exceeds half a bin
            if mean_residual > bin_capacity as f64 * 0.5 {
                score += 10.0;
            }
            // gen44: block new bins when mean residual alone can absorb the item
            if mean_residual >= item_size as f64 + 3.0 && fitting_bins_count > 0 {
                score += 5.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // reward bins whose post-residual matches next item exactly
        if next_item_size > 0 && post_residual == next_item_size {
