        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
        // extra reward for very tight leftover fits on existing bins
        if post_residual > 0 && post_residual <= 3 {
            score -= 4.0;
        }
        // gen39: prefer bins whose post-residual stays below mean residual (compact packing)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
            if slack <= 2.0 {
                score -= 6.0;
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // gen45: near-chain fit bonus (slack within 4)
        if post_residual > next_item_size && post_residual - next_item_size <= 4 {
            score -= 8.0;
        }
        // gen45: logarithmic gap penalty for over-large slack
        if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap.ln().max(0.0);
        }
    } else {
        score = post_residual as f64 * 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Best-fit flavor
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Awkward residual zone
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }
    if post_residual > 12 && post_residual < 22 {
        score += 6.0 + 5.0 * (1.0 - progress);
    }

    // Pressure-based consolidation
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Large residual handling
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 60.0;
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            // gen45: if some open bin leaves a near-exact chain fit for the next item,
            // strongly discourage opening a fresh bin
            if fitting_bins_count > 0 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                score += 4.0;
            }
            // gen45: penalize new bins when mean residual can absorb small items
            if mean_residual >= item_size as f64 + 8.0 {
                score += 8.0;
            }
            // gen45: discourage new bins when a near-perfect chain fit exists elsewhere
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 3.0;
            }
            if progress > 0.9 && fitting_bins_count > 0 {
                score += 3.0;
            }
        }
    } else {
        // Existing-bin refinement: discourage near-perfect fits elsewhere from being wasted
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 4.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // gen45: reward bins whose post-residual matches next item exactly (chain completion)
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0;
        }
        // gen45: gentle penalty for leaving medium dead zones relative to mean residual
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight packing)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is costlier, so penalize large residuals more
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (near-zero post residual) more strongly as stream advances
    let tight = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tight * (0.5 + progress);

    // Dead-space penalty: residual too small for typical future items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 15.0 * (1.0 - pr / ni) * (0.5 + progress);
        } else {
            // reward leaving room for the lookahead item
            score -= 10.0 * (1.0 - ((pr - ni) / cap)).powi(2);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild preference for bins with below-average residual (consolidate waste)
    let diff = mean_residual - bin_residual as f64;
    score -= 0.1 * diff;

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

