    // lookahead item (k=2 lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual positive but cannot fit next item: mild penalty
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids
    // opening a new bin, but only if the fit is not too wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
