        score += 40.0 + 12.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
