        // full they already are relative to the mean.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Tightness bonus: prefer filling bins with large item-to-residual ratio.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 15.0 * tightness;
