    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Large residual handling
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 60.0;
    }

    // chain-fit dead-space killer
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // unfillable middle penalty
    if post_residual > 15 && (post_residual as f64) > mean_residual * 1.5 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 3.0;
            }
            if mean_residual >= item_size as f64 + 8.0 {
                score += 8.0;
            }
            if progress > 0.7 && fitting_bins_count >= 1 && post_residual <= 10 {
                score += 6.0;
            }
            if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 1 {
                score -= 4.0;
            }
            // gen46: any existing bin that can chain the next item discourages new bins
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
                score += 5.0;
            }
            // gen46: new bins wasteful when mean residual alone can absorb the item
            if (mean_residual as u32) >= item_size && fitting_bins_count > 1 {
                score += 10.0;
            }
            // gen46: late stream, strongly prefer existing bins unless nothing fits
            if progress > 0.85 && fitting_bins_count > 0 {
                score += 9.0;
            }
            // gen46: near-perfect fit exists elsewhere -> strongly discourage new bin
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual == next_item_size {
                score += 20.0;
            }
            // gen46: dead-space guard — new bin leaves capacity-sized residual; penalize when item is small
            if item_size <= bin_capacity / 5 && fitting_bins_count > 0 {
                score += 12.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0;
        }
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 3.0;
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 && progress > 0.5 {
            score -= 3.0;
        }
        // gen46: reward bins whose residual exactly matches next item regardless of progress
        if next_item_size > 0 && bin_residual == next_item_size + item_size {
            score -= 7.0;
        }
        // gen46: two-step chain anticipation — residual can host next item then still fit a small tail
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail >= 1 && tail <= 6 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post residual -> huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits snugly (leaves little waste after the pair)
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= (30.0 - pair_waste.min(30) as f64) * 0.8;
    } else if next_item_size > 0 {
        // next item cannot reuse this residual: penalize relative to its size
        let miss = (next_item_size as f64 - post_residual as f64).min(40.0);
        score += miss * 0.5;
    }

    // Reward tight fits overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Compare residual against mean residual: keep bins near the mean balanced
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space that no future item (min size ~1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in stream: prefer filling existing bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    } else {
        // new-bin candidate: add a mild opening penalty so it only wins on bad fits
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit reward (strengthened)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 18.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 1.5;
            if slack <= 2.0 {
                score -= 8.0;
            }
        } else {
            score += 150.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
        if post_residual == next_item_size {
            score -= 550.0;
        }
        // near-chain fit bonus (slack within 4)
        if post_residual > next_item_size && post_residual - next_item_size <= 4 {
            score -= 10.0;
        }
        // logarithmic gap penalty for over-large slack
        if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.35 * gap.ln().max(0.0);
        }
    } else {
        score = post_residual as f64 * 3.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Best-fit flavor
    score += (bin_residual as f64 - mean_residual) * 0.8;
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Awkward residual zone
    if post_residual > 0 && post_residual < 12 {
        score += 28.0 + 12.0 * (1.0 - progress);
    } else if post_residual < 22 {
        score += 9.0;
    }
    if post_residual > 12 && post_residual < 22 {
        score += 6.0 + 5.0 * (1.0 - progress);
    }

    // Pressure-based consolidation
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let slack_pressure = (mean_residual / 30.0).min(2.0);
    if post_residual >= 22 {
        score -= (3.0 + slack_pressure) * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Large residual handling
    if post_residual > 30 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0 + 0.08 * (post_residual as f64 - 30.0);
        }
    }

    // Late-stream consolidation
    if bin_residual < bin_capacity {
        score -= progress * 60.0;
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            if next_item_size > 0 && next_item_size > bin_capacity / 2 {
                score -= 18.0;
            }
            if mean_residual > 35.0 {
                score -= 5.0;
            }
            if fitting_bins_count <= 2 && item_size < bin_capacity / 4 {
                score -= 7.0;
            }
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && fitting_bins_count > 2 {
                score -= 12.0;
            }
            if next_item_size > 0 && item_size + next_item_size > bin_capacity && item_size >= bin_capacity * 2 / 3 {
                score -= 10.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual * 0.15 {
                score -= 6.0;
            }
            if fitting_bins_count > 4 && item_size <= 6 {
                score -= 9.0;
            }
            if progress < 0.3 && mean_residual < 15.0 {
                score -= 4.0;
            }
            if mean_residual > 25.0 {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 5.0;
            }
            if fitting_bins_count > 2 {
                score += 14.0;
            }
            if item_size > bin_capacity * 3 / 4 {
                score += 8.0;
            }
            if progress > 0.8 && fitting_bins_count > 0 {
                score += 5.0;
            }
            if progress > 0.6 && fitting_bins_count > 0 && post_residual < next_item_size.max(1) {
                score -= 4.0;
            }
            // gen46: if some open bin leaves a near-exact chain fit for the next item,
            // strongly discourage opening a fresh bin
            if fitting_bins_count > 0 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                score += 5.0;
            }
            // penalize new bins when mean residual can absorb small items
            if mean_residual >= item_size as f64 + 8.0 {
                score += 10.0;
            }
            // discourage new bins when a near-perfect chain fit exists elsewhere
            if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
                score -= 5.0;
            }
            if progress > 0.9 && fitting_bins_count > 0 {
                score += 3.0;
            }
        }
    } else {
        // Existing-bin refinement
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 4.0;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // reward bins whose post-residual matches next item exactly (chain completion)
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0;
        }
        // gentle penalty for leaving medium dead zones relative to mean residual
        if post_residual > 25 && (post_residual as f64) > mean_residual * 1.6 {
            score += 4.0;
        }
        // gen46: penalize residuals just above the next item size that waste space
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 8 && post_residual - next_item_size > 4 {
            score += 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let next = next_item_size as f64;

    // Time horizon: progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this placement
    let fill = item / cap;
    let waste = post / cap; // smaller post_residual => better fit

    // Base: prefer small post residual (tight packing)
    let mut score = post;

    // Reward near-perfect fits strongly (dead-space penalty is superlinear)
    if post > 0.0 {
        score += 12.0 * (post / cap).powf(1.7) * cap;
    } else {
        score -= 40.0; // exact fit bonus
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next > 0.0 {
        if (post - next).abs() < f64::EPSILON {
            score -= 60.0;
        } else if next <= post {
            // next item can go here too: mild reward proportional to how snugly
            score -= 15.0 * (1.0 - (post - next) / cap);
        } else {
            // next item won't fit after this placement: penalize a bit more
            // when this bin was a scarce option
            score += 8.0 * (next - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // many options: prefer the tightest, discourage wasting a scarce large residual
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global balance: penalize bins whose residual deviates favorably from mean
    // (prefer using bins with below-average residual to consolidate space)
    let dev = residual - mean_residual;
    score += 0.15 * dev;

    // Late in the stream: consolidate aggressively, avoid opening new bins
    let new_bin = (bin_residual as u32 == bin_capacity);
    if new_bin {
        // Opening a new bin: base cost, cheaper early, expensive late
        let open_cost = 30.0 + 60.0 * progress;
        score = cap as f64 * 0.9 + open_cost;
        // Only attractive if item is large relative to capacity and no tight fit exists
        score -= 20.0 * fill;
        if next > 0.0 && next <= post {
            score -= 10.0; // fresh bin has room for lookahead item
        }
    } else {
        // Using an existing bin gets a discount that grows over time
        score -= 5.0 + 10.0 * progress;
    }

    // Congestion: many open bins -> discourage spreading, favor filling existing
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * if new_bin { 1.0 } else { -0.5 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_frac = post / cap;

    // Base: prefer tight fits, with a non-linear (quadratic) penalty on waste.
    let mut score = post + 40.0 * post_frac * post_frac;

    // Smooth coupling of waste penalty with stream progress: later in the stream,
    // dead space matters more (fewer chances to fill it).
    score += 60.0 * post_frac * post_frac * progress;

    // Smoothly reward bins that can also host the lookahead item (chained fit).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let chain_quality = 1.0 - ((post - next_item_size as f64) / cap);
        score -= 25.0 * chain_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that fails the lookahead, scaled by gap size.
        score += 15.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // with a smooth factor depending on how tight the fit is.
    if fitting_bins_count == 1 {
        let tightness = 1.0 - post_frac;
        score -= 30.0 + 30.0 * tightness;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // smoothly scaled by how far this bin's residual deviates from the mean.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Slight preference for fuller bins overall (smooth in post_residual).
    score -= 0.05 * (cap - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
